class ODETokenFlow(nn.Module):
    def __init__(self, dim=128, steps=4):
        super().__init__()
        self.field = nn.Sequential(nn.Linear(dim, dim), nn.Tanh(), nn.Linear(dim, dim))
        self.steps = steps
    def forward(self, x):  # (B,T,C)
        dt = 1.0/self.steps
        for _ in range(self.steps):
            x = x + dt * self.field(x)  # Euler integrate token state
        return x

class PhoneticBottleneck(nn.Module):
    def __init__(self, dim=128, phon_dim=24):
        super().__init__()
        self.to_phon = nn.Linear(dim, phon_dim)
        self.from_phon = nn.Linear(phon_dim, dim)
    def forward(self, x):
        p = self.to_phon(x)
        return self.from_phon(p)  # force info through phonetic latent

class MemoryTape(nn.Module):
    def __init__(self, C=128, T=128, dim=128, tape_len=32):
        super().__init__()
        self.tape = nn.Parameter(torch.randn(tape_len, dim))
        self.addr = nn.Linear(dim, tape_len)
        self.write = nn.Linear(dim, dim)
    def forward(self, x):  # (B, C, T)
        w = torch.softmax(self.addr(x), -1)  # (B, C, tape_len)
        read = torch.einsum('btn,nc->btc', w, self.tape)  # (B, C, dim)
        return x + read

class GrammarLatticeGate(nn.Module):
    def __init__(self, C=128, T=128, dim=128, states=16):
        super().__init__()
        self.trans = nn.Parameter(torch.rand(states, states))
        self.embed = nn.Linear(dim, states)
        self.out = nn.Linear(states, dim)
    def forward(self, x):  # (B, C, T)
        h = x.transpose(1, 2)  # (B, T, C)
        s = torch.softmax(self.embed(h), -1)  # (B, T, states)
        trans = torch.softmax(self.trans, -1)
        s_next = torch.einsum('bts,st->bts', s, trans)  # (B, T, states)
        out = self.out(s_next)  # (B, T, dim)
        return x + out.transpose(1, 2)  # (B, C, T)

class AnisotropicDiffusionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, steps=2):
        super().__init__()
        self.kernel = nn.Parameter(torch.tensor([0.25, 0.5, 0.25]))  # learnable 1D kernel
        self.steps = steps
    def forward(self, x):  # (B, C, T)
        B, C, T = x.shape
        h = x.transpose(1, 2).reshape(B * C, 1, T)
        for _ in range(self.steps):
            lap = torch.conv1d(h, self.kernel[None, None, :].expand(1, 1, -1), padding=1)
            h = h + 0.2 * (lap - h)
        return h.reshape(B, C, T)

class QMCSampleGate(nn.Module):
    def __init__(self, dim=128, experts=4):
        super().__init__()
        self.experts = nn.ModuleList([nn.Linear(dim, dim) for _ in range(experts)])
        self.seq = self._halton(experts)  # low-discrepancy points
    def _halton(self, n):
        return torch.rand(n)  # placeholder for deterministic Halton sequence
    def forward(self, x):
        idx = (self.seq * x.shape[1]).long() % len(self.experts)
        return sum(e(x) for i,e in enumerate(self.experts) if (idx==i).any())

class SymmetryEquivariantMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.w = nn.Linear(dim, dim)
        self.reflect = nn.Parameter(torch.eye(dim))  # learnable involution
    def forward(self, x):  # (B, C, T)
        fwd = self.w(x)
        rev = torch.flip(self.w(torch.flip(x, 1)), (1,))
        return 0.5 * (fwd + rev @ self.reflect)  # equivariant avg

class HyperbolicTokenMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, curv=1.0):
        super().__init__()
        self.c = curv
        self.lin = nn.Linear(dim, dim)
    def exp_map(self, x):
        return torch.tanh(torch.norm(x, -1, keepdim=True) / (self.c ** 0.5) + 1e-5) * x
    def forward(self, x):  # (B, C, T)
        h = self.exp_map(x)  # to hyperbolic
        mixed = self.lin(h)
        return torch.log1p(torch.norm(mixed, -1, keepdim=True)) * mixed  # log-map back

class CapsuleRoute1D(nn.Module):
    def __init__(self, C=128, T=128, dim=128, caps=8):
        super().__init__()
        self.caps_proj = nn.Linear(dim, caps)
        self.routing = nn.Parameter(torch.randn(caps, dim))
    def forward(self, x):  # (B, C, T)
        h = x.transpose(1, 2)  # (B, T, C)
        proj = self.caps_proj(h)  # (B, T, caps)
        att = torch.softmax(proj, -1)  # (B, T, caps)
        out = torch.einsum('btk,kc->btc', att, self.routing)  # (B, T, C)
        return out.transpose(1, 2)  # (B, C, T)

class KolmogorovArnoldMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, grid=8):
        super().__init__()
        self.coef = nn.Parameter(torch.randn(dim, grid))  # spline basis weights
        self.grid = grid
    def forward(self, x):  # (B, C, T)
        g = torch.linspace(0, 1, self.grid, device=x.device)
        bases = torch.exp(-((x[..., None] - g) ** 2))  # (B, C, T, grid)
        out = torch.einsum('bctg,cg->bct', bases, self.coef)  # (B, C, T)
        return out

class SpikingLIFMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, thr=1.0):
        super().__init__(); self.rec=nn.Linear(C,C); self.thr=thr
    def forward(self, x):
        B,T,C=x.shape; v=0.0; outs=[]
        for t in range(T):
            v=0.9*v+self.rec(x[:,t])
            s=(v>self.thr).float(); v=v*(1-s)
            outs.append(x[:,t]+0.5*s*torch.relu(v))
        return torch.stack(outs,1)

class STDPHebbianMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
    def forward(self, x):
        B,T,C=x.shape
        m=torch.tril(torch.ones(T,T),0).to(x.device)
        corr=torch.einsum('btc,bsc->bts',x,x)*m
        corr=torch.tanh(corr/(C**0.5))
        return x+torch.einsum('bts,bsc->btc',corr,x)

class NeurogenesisMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C); self.grow=nn.Linear(C,C)
    def forward(self, x):
        y=self.fc(x)
        mask=(torch.rand_like(y)>0.92).float()
        return x+y*(1-mask)+self.grow(x)*mask

class SlimeMoldMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, iters=5):
        super().__init__(); self.iters=iters; self.D=nn.Parameter(torch.rand(T,T))
    def forward(self, x):
        B,T,C=x.shape; D=torch.softmax(self.D*torch.tril(torch.ones(T,T),0).to(x.device),1)
        for _ in range(self.iters):
            x=x+0.5*(torch.einsum('ts,btc->bsc',D,x)-x)
        return x

class AntColonyMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.pher=nn.Parameter(torch.ones(T,T)*0.1)
    def forward(self, x):
        B,T,C=x.shape; d=torch.softmax(self.pher*torch.tril(torch.ones(T,T),0).to(x.device),1)
        dep=torch.tanh(torch.corrcoef(x[0].T)).abs()
        self.pher.data+=0.01*dep
        return x+0.5*torch.einsum('ts,btc->bsc',d,x)

class DNAComplementMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Linear(C,C); self.b=nn.Linear(C,C)
    def forward(self, x):
        A=self.a(x); B=self.b(x)
        M=torch.einsum('btc,bsc->bts',A,B)*torch.tril(torch.ones(x.shape[1],x.shape[1]),0).to(x.device)
        return x+0.3*torch.einsum('bts,bsc->btc',torch.tanh(M),B)

class TuringMorphogenMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.f=nn.Linear(C,C); self.g=nn.Linear(C,C)
    def forward(self, x):
        lap=x-torch.roll(x,1,1)-torch.roll(x,-1,1)
        react=torch.tanh(self.f(x))-torch.tanh(self.g(x))
        return x+0.1*(lap+react)

class CPGOscillatorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.omega=nn.Parameter(torch.rand(T)*0.1)
    def forward(self, x):
        B,T,C=x.shape; j=torch.arange(T,device=x.device).float()
        ph=torch.sin(self.omega.unsqueeze(1)*j.unsqueeze(0))
        m=torch.softmax(ph*torch.tril(torch.ones(T,T),0).to(x.device),1)
        return x+torch.einsum('ts,bsc->btc',m,x)-x.roll(1,1)

class QuorumSensingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.k=nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        dens=torch.sigmoid(x.mean(-1)).mean(-1,keepdim=True)
        signal=torch.sigmoid((dens-self.k)*5)
        mean=x.mean(1,keepdim=True)
        return x+signal.unsqueeze(-1)*(mean-x)

class ImmuneClonalMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.rec=nn.Linear(C,C)
    def forward(self, x):
        s=torch.sigmoid(self.rec(x)); a=s*x
        clone=a*torch.relu(s-0.5); supp=a*(s<0.5).float()*-1
        return x+0.3*(clone+supp)

class SynapticPruningMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=8):
        super().__init__(); self.fc=nn.Linear(C,C); self.k=k
    def forward(self, x):
        w=self.fc.weight; mask=torch.zeros_like(w)
        mask.scatter_(1,w.abs().topk(self.k,1).indices,1)
        return x+nn.functional.linear(x,self.fc.weight*mask,bias=None)

class GeneticCrossoverMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.mask=nn.Parameter(torch.rand(C))
    def forward(self, x):
        m=(self.mask>0.5).float()
        nb=x.roll(1,1)
        return x*m+nb*(1-m)

class QuantumGateMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.W = nn.Linear(C, C)
        self.theta = nn.Parameter(torch.randn(C//2, 2)*0.1)
    def forward(self, x):
        y = self.W(x)
        rot = torch.cat([y[...,1::2], y[...,0::2]], -1) * torch.sin(self.theta).mean(-1, keepdim=True)
        return y + 0.1*rot

class IsingGlauberMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.J = nn.Parameter(torch.randn(C, C).triu(1)*0.1)
        self.h = nn.Parameter(torch.zeros(C))
    def forward(self, x):
        s = torch.tanh(x)
        field = (s @ (self.J + self.J.T) + self.h) * s
        return x + 0.1*torch.tanh(field)

class HamiltonianTrotterMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.k = nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        xn = torch.cat([x[:,:1], x[:,:-1]], 1)
        grad = (x - xn)
        return x - self.k * grad

class LagrangianOscillatorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.m = nn.Parameter(torch.ones(C))
        self.k = nn.Parameter(torch.ones(C)*0.5)
    def forward(self, x):
        acc = self.k*(torch.cat([x[:,1:],x[:,:1]],1) + torch.cat([x[:,-1:],x[:,:-1]],1) - 2*x)
        return x + 0.1*acc/self.m

class TreeTensorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.A = nn.Parameter(torch.randn(C, C, 4)/C**0.5)
    def forward(self, x):
        v = x
        for _ in range(2):
            v = torch.einsum('btc,cdk->btdk', v, self.A).sum(-1)
        return x + v

class NavierStokesFreqMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, modes=8):
        super().__init__()
        self.modes = modes
        self.w = nn.Parameter(torch.randn(modes, C, 2)*0.1)
    def forward(self, x):
        f = torch.fft.rfft(x, dim=1)
        f[:,:self.modes] = torch.view_as_complex(self.w) * f[:,:self.modes]
        return x + torch.fft.irfft(f, n=x.size(1), dim=1)

class VortexInductionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.g = nn.Parameter(torch.tensor(0.3))
    def forward(self, x):
        T = x.size(1)
        d = (torch.arange(T).float() - torch.arange(T).float()[:,None]).abs().clamp(min=1)
        vel = self.g / d
        return x + 0.1*torch.tanh(torch.einsum('ij,btj->bti', vel, x))

class LorentzBoostMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.beta = nn.Parameter(torch.zeros(C))
    def forward(self, x):
        g = 1/torch.sqrt(1-self.beta**2+1e-6)
        xt = x.roll(1, 1)
        out = g[:,None,None]*(x - self.beta[:,None,None]*xt)
        return x + 0.1*(out - x)

class FreeEnergyMinMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.E = nn.Linear(C, C)
        self.S = nn.Linear(C, C)
        self.T = nn.Parameter(torch.tensor(1.0))
    def forward(self, x):
        F = self.E(x) - self.T*self.S(x)
        return x - 0.1*torch.tanh(F)

class PathIntegralMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=5):
        super().__init__()
        self.K = K
        self.a = nn.Parameter(torch.randn(K)*0.1)
    def forward(self, x):
        out = 0
        for k in range(1, self.K+1):
            out = out + self.a[k-1]*x.roll(k, 1)
        return x + out

class LatticeGaugeLoopMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.U = nn.Parameter(torch.randn(C)*0.1)
    def forward(self, x):
        phase = torch.cumsum(self.U, 0)
        w = torch.sin(phase - phase.mean())[None,:,None]
        return x + 0.1*torch.tanh(x * w)

class FractalIFSMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=4, it=3):
        super().__init__(); self.k=k; self.it=it
        self.w=nn.Parameter(torch.randn(k,C,C)*0.3); self.b=nn.Parameter(torch.randn(k,C))
        self.a=nn.Parameter(torch.rand(k))
    def forward(self,x):
        for _ in range(self.it):
            y=sum(F.softmax(self.a,0)[i]*(x@self.w[i]+self.b[i]) for i in range(self.k))
            x=x+0.5*(y-x)
        return x

class BraidGroupMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Parameter(torch.rand(C)); self.b=nn.Parameter(torch.rand(C))
    def forward(self,x):
        o=x.clone()
        for t in range(1,x.size(1)):
            l=x[:,t-1]; r=x[:,t]
            o[:,t-1]=self.a*l+self.b*r; o[:,t]=self.b*l+self.a*r
        return o

class FunctorCompositionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=3):
        super().__init__(); self.F=nn.Parameter(torch.randn(n,C,C))
    def forward(self,x):
        M=self.F[0].clone()
        for i in range(1,len(self.F)): M=self.F[i]@M
        return x@M

class NonabelianGroupConv(nn.Module):
    def __init__(self, C=128, T=128, dim=128, g=4):
        super().__init__(); self.g=g; self.f=nn.Parameter(torch.randn(g,C,C))
    def forward(self,x):
        T=x.size(1); o=torch.zeros_like(x)
        for s in range(self.g):
            sh=s*T//self.g
            o+=torch.roll(x,shifts=sh,dims=1)@self.f[s]
        return o/self.g

class TropicalMinplusMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, w=3):
        super().__init__(); self.w=w; self.A=nn.Parameter(torch.rand(w,C,C))
    def forward(self,x):
        o=torch.full_like(x,float('inf'))
        for i in range(self.w):
            v=torch.roll(x,shifts=i,dims=1)@self.A[i]
            o=torch.minimum(o,v)
        return o

class PadicTreeMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, p=2, lv=4):
        super().__init__(); self.p=p; self.lv=lv; self.w=nn.Parameter(torch.rand(lv,C,C))
    def forward(self,x):
        B,T,C=x.shape; o=x.clone()
        for t in range(T):
            for l in range(self.lv):
                b=self.p**l; nb=x[:, (t//b)*b:(t//b)*b+b]
                o[:,t]+=(nb.mean(1)@self.w[l])/self.lv
        return o

class CliffordRotorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.r=nn.Parameter(torch.randn(C))
    def forward(self,x):
        q=torch.tanh(self.r)
        return x*(1+q)+torch.roll(x,1,1)*q

class PersistentHomologyMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.g=nn.Parameter(torch.rand(C))
    def forward(self,x):
        d=torch.cdist(x,x); mask=(d<0.5)
        agg=(mask.float()@x)/mask.float().sum(-1,keepdim=True).clamp(1)
        return x+self.g*agg-self.g*x.mean(1,keepdim=True)

class RicciFlowMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.s=nn.Parameter(torch.rand(C))
    def forward(self,x):
        w=torch.softmax(torch.cdist(x,x)/-2,dim=-1)
        lap=x-w@x
        return x-self.s*lap

class WassersteinOTMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=8):
        super().__init__(); self.proto=nn.Parameter(torch.randn(n,C))
    def forward(self,x):
        d=-torch.cdist(x,self.proto); P=torch.softmax(d,2)
        return x+(P@self.proto-x)*0.1

class SheafStalkMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.r=nn.Linear(C,C); self.l=nn.Linear(C,C)
    def forward(self,x):
        diff=self.r(x)-self.l(torch.roll(x,1,1))
        return x-0.1*(diff+torch.roll(diff,-1,1))

class GrassmannianSubspaceMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, r=8):
        super().__init__(); self.B=nn.Parameter(torch.randn(C,r))
    def forward(self,x):
        B,_=torch.qr(self.B); proj=x@B@B.t()
        return x+(proj-x)*0.1

class PolarTransformMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, logT=8):
        super().__init__(); self.logT=logT
        self.frozen=nn.Parameter(torch.rand(C))
    def forward(self, x):
        y=x.clone()
        for _ in range(self.logT):
            a,b=y[...,::2,:],y[...,1::2,:]; y=torch.cat([a+b,a-b],-2)
        return torch.tanh(y)*self.frozen.view(1,1,-1)

class LDPCMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.H=nn.Parameter((torch.rand(C,T)>0.92).float(),requires_grad=False); self.W=nn.Linear(C,C)
    def forward(self, x):
        m=torch.tanh(x@self.W)
        for _ in range(3):
            c=torch.tanh(self.H@m.transpose(1,2)); m=torch.tanh(self.H.t()@c.transpose(1,2)+x)
        return x+0.1*m

class ReedSolomonSyndromeMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.roots=nn.Parameter(torch.linspace(-1,1,T),requires_grad=False); self.P=nn.Linear(C,C)
    def forward(self, x):
        syn=torch.tanh(x@self.P)*self.roots[None,:,None]
        err=(torch.tanh(syn.permute(0,2,1)@syn)).permute(0,2,1)
        return x-0.1*err

class HuffmanPrefixGate(nn.Module):
    def __init__(self, C=128, T=128, dim=128, L=8):
        super().__init__(); self.code=nn.Parameter(torch.randn(C,L)); self.merge=nn.Linear(2*C,C)
    def forward(self, x):
        w=torch.softmax(self.code,0); g=(x@w).sigmoid()
        paired=torch.cat([x[:,:-1],x[:,1:]],-1); return x+0.1*self.merge(paired).sigmoid()*g.unsqueeze(-1)

class LZ77DictionaryMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, W=64):
        super().__init__(); self.W=W
    def forward(self, x):
        ref=x[:,max(0,x.size(1)-self.W-1):-1]; sim=torch.softmax((x[:,:-1]*ref).sum(-1,keepdim=True)/ref.norm(2,-1,keepdim=True),-1)
        return x+0.1*(ref*sim- x[:,1:]).flip(1)

class InformationBottleneckMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.mu=nn.Linear(C,C); self.lv=nn.Linear(C,C)
    def forward(self, x):
        mu,lv=self.mu(x),self.lv(x); z=mu+(0.5*lv).exp()*torch.randn_like(x)
        return z

class RateDistortionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=256, lam=0.1):
        super().__init__(); self.cb=nn.Parameter(torch.randn(K,C)); self.lam=lam
    def forward(self, x):
        d=(x[:,:,None,:]-self.cb).pow(2).sum(-1); q=self.cb[d.argmin(-1)]
        return x+self.lam*(q-x)

class EntropyBottleneckMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.lo=nn.Parameter(torch.zeros(C)); self.sc=nn.Parameter(torch.ones(C))
    def forward(self, x):
        u=torch.rand_like(x)-0.5; y=x+u*self.sc+self.lo
        return torch.round(y)-self.lo

class ArithmeticCDFMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.cdf=nn.Parameter(torch.sort(torch.rand(T,C),0).values)
    def forward(self, x):
        cdf=torch.softmax(self.cdf,0); blend=(cdf.unsqueeze(0)*x).sum(1,keepdim=True).expand_as(x)
        return 0.5*x+0.5*blend

class ContrastivePredictiveMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Parameter(torch.eye(C))
    def forward(self, x):
        f=x@self.W; s=torch.einsum('btc,bkc->btk',x,f); ctx=torch.softmax(s,-1)@f
        return x+0.1*ctx

class VectorQuantizationSourceMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=128):
        super().__init__(); self.cb=nn.Parameter(torch.randn(K,C))
    def forward(self, x):
        d=(x[:,:,None,:]-self.cb).pow(2).sum(-1); return self.cb[d.argmin(-1)]

class TurboInterleaveMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.perm=nn.Parameter(torch.randperm(C),requires_grad=False); self.W=nn.Linear(C,C)
    def forward(self, x):
        a=torch.tanh(x@self.W); b=a[:,:,self.perm]
        for _ in range(2):
            a=torch.tanh(a+b.flip(1)); b=torch.tanh(b+a[:,:,self.perm])
        return x+0.1*(a+b)

class FractionalFourierMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a = nn.Parameter(torch.tensor(0.5)); self.proj = nn.Linear(C, C)
    def forward(self, x):
        T = x.shape[1]; n = torch.arange(T, device=x.device).float()
        W = torch.exp(-1j*torch.pi/2*(torch.cos(torch.pi/2*torch.tanh(self.a))*n[:,None]**2 + torch.sin(torch.pi/2*torch.tanh(self.a))*n[:,None]*n[None,:]))
        return self.proj(torch.einsum('btc,ts->bsc', x, W.to(x.dtype)).real)

class ChirpletMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=8):
        super().__init__()
        self.beta = nn.Parameter(torch.randn(M)*0.1)
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        T = x.shape[1]; t = torch.linspace(-1,1,T,device=x.device); X = torch.fft.fft(x,dim=1); out = 0
        for b in self.beta:
            W = torch.exp(1j*torch.pi*b*t**2); out = out + torch.fft.ifft(X*W, dim=1)
        return self.proj(out.real)

class WignerVilleMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1)
        A = torch.fft.ifft(torch.abs(X)**2, dim=1)  # pseudo Wigner-Ville autocorrelation
        return self.proj(A.real)

class HilbertHuangMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=6):
        super().__init__(); self.cent = nn.Parameter(torch.rand(K)*0.5); self.w = nn.Parameter(torch.ones(K)*0.05); self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); T = x.shape[1]; f = torch.linspace(0,1,T,device=x.device); out = 0
        for i in range(len(self.cent)):
            H = torch.sigmoid(8*(f-self.cent[i]))*(1-torch.sigmoid(8*(f-self.cent[i]-self.w[i]))); out = out + torch.fft.ifft(X*H, dim=1)
        return self.proj(out.real)

class AnalyticSignalMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); X[...,1:X.shape[1]//2,:] *= 2  # analytic: double positive freqs
        a = torch.fft.ifft(X, dim=1)
        return self.proj(a.abs())

class ZTransformMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.theta = nn.Parameter(torch.rand(1)*6.28)
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        T = x.shape[1]; n = torch.arange(T, device=x.device).float()
        z = torch.exp(1j*self.theta); W = torch.pow(z, n[:,None]-n[None,:])
        return self.proj(torch.einsum('btc,ts->bsc', x, W.to(x.dtype)).real)

class WaveletPacketMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=6):
        super().__init__(); self.lo = nn.Parameter(torch.rand(K)*0.5); self.w = nn.Parameter(torch.ones(K)*0.05); self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); T = x.shape[1]; f = torch.linspace(0,1,T,device=x.device); out = 0
        for i in range(len(self.lo)):
            H = torch.exp(-((f-self.lo[i])/self.w[i])**2)+torch.exp(-((f-(1-self.lo[i]))/self.w[i])**2); out = out + torch.fft.ifft(X*H, dim=1)
        return self.proj(out.real)

class RidgeletMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=8):
        super().__init__()
        self.slopes = nn.Parameter(torch.randn(M)*0.5); self.proj = nn.Linear(C, C)
    def forward(self, x):
        T = x.shape[1]; t = torch.arange(T, device=x.device).float(); out = 0
        for s in self.slopes:
            W = torch.exp(1j*(s*t[:,None]*t[None,:])); out = out + torch.einsum('btc,ts->bsc', x, W.to(x.dtype))
        return self.proj(out.real)

class CurveletMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=6):
        super().__init__()
        self.scales = nn.Parameter(torch.rand(K)*0.5); self.ws = nn.Parameter(torch.ones(K)*0.05)
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); T = x.shape[1]; f = torch.linspace(0,1,T,device=x.device); out = 0
        for i in range(len(self.scales)):
            H = torch.exp(-((f-self.scales[i])/self.ws[i])**2); out = out + torch.fft.ifft(X*H, dim=1)
        return self.proj(out.real)

class LearnedGaborMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=8):
        super().__init__()
        self.cent = nn.Parameter(torch.randn(M)*0.3); self.phase = nn.Parameter(torch.randn(M))
        self.w = nn.Parameter(torch.ones(M)*0.05); self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); T = x.shape[1]; f = torch.linspace(-0.5,0.5,T,device=x.device); out = 0
        for i in range(len(self.cent)):
            H = torch.exp(-((f-self.cent[i])/self.w[i])**2)*torch.exp(1j*self.phase[i]); out = out + torch.fft.ifft(X*H, dim=1)
        return self.proj(out.real)

class STFTLearnedWindowMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.window = nn.Parameter(torch.ones(C)*0.1); self.proj = nn.Linear(C, C)
    def forward(self, x):
        T = x.shape[1]; w = torch.softmax(self.window[:T], 0)
        W = torch.linalg.circulant(w).to(x.device)
        return self.proj(torch.einsum('btc,ts->bsc', x, W))

class StockwellMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=6):
        super().__init__()
        self.freqs = nn.Parameter(torch.rand(K)*0.5); self.proj = nn.Linear(C, C)
    def forward(self, x):
        X = torch.fft.fft(x, dim=1); T = x.shape[1]; f = torch.linspace(0,1,T,device=x.device); out = 0
        for i in range(len(self.freqs)):
            H = torch.exp(-((f-self.freqs[i])/(self.freqs[i]+1e-3))**2); out = out + torch.fft.ifft(X*H, dim=1)
        return self.proj(out.real)

class KalmanTokenSmoother(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.A = nn.Linear(C, C)
    def forward(self, x):
        B, T, C = x.size(); m = x.new_zeros(B, C); fwd = []
        for t in range(T):
            m = torch.tanh(self.A(m)) + x[:, t]; fwd.append(m)
        s = fwd[-1]; sm = [s]
        for t in range(T - 2, -1, -1):
            s = 0.5 * (fwd[t] + s); sm.append(s)
        return torch.stack(sm[::-1], 1)

class LQRController(nn.Module):
    def __init__(self, C=128, T=128, dim=128, W=3):
        super().__init__(); self.W = W; self.K = nn.Parameter(torch.randn(W, C, C) * 0.1)
    def forward(self, x):
        B, T, C = x.size(); y = x.clone()
        for t in range(self.W, T):
            u = sum((self.K[w] @ x[:, t - w - 1].T).T for w in range(self.W))
            y[:, t] = x[:, t] + 0.1 * torch.tanh(u)
        return y

class LyapunovGate(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.w = nn.Linear(C, C)
    def forward(self, x):
        B, T, C = x.size(); out = []; prev = x.new_zeros(B, C)
        for t in range(T):
            nx = torch.sigmoid(self.w(x[:, t])) * x[:, t]
            dE = (nx.norm(2, 1) ** 2 - prev.norm(2, 1) ** 2).mean()
            out.append(nx if dE <= 0 else 0.5 * (nx + prev)); prev = nx
        return torch.stack(out, 1)

class PortHamiltonian(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.J = nn.Linear(C, C); self.D = nn.Parameter(torch.eye(C) * 0.1)
    def forward(self, x):
        B, T, C = x.size()
        for t in range(1, T):
            g = (self.J.weight - self.J.weight.T) @ x[:, t - 1].T
            d = (g - self.D @ x[:, t - 1].T).T
            x[:, t] = x[:, t] - 0.1 * d
        return x

class KuramotoMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=0.5):
        super().__init__(); self.K = K; self.omega = nn.Parameter(torch.randn(C) * 0.1)
    def forward(self, x):
        B, T, C = x.size(); th = torch.cumsum(x, 1)
        for t in range(1, T):
            coup = torch.sin(th[:, t - 1] - th[:, t]).mean(-1, keepdim=True)
            th[:, t] = th[:, t] + 0.1 * self.omega + self.K * coup
        return torch.sin(th)

class LorenzDynamics(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.s = nn.Linear(C, 3); self.r = 28.0; self.b = 2.667; self.w = 10.0
    def forward(self, x):
        B, T, C = x.size(); z = torch.tanh(self.s(x))
        for t in range(1, T):
            X, Y, Z = z[:, t - 1].chunk(3, -1)
            dz = torch.cat([self.w * (Y - X), X * (self.r - Z) - Y, X * Y - self.b * Z], -1)
            z[:, t] = z[:, t] + 0.02 * dz
        return z @ self.s.weight.T

class RosslerDynamics(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.s = nn.Linear(C, 3); self.a = 0.2; self.b = 0.2; self.c = 5.7
    def forward(self, x):
        B, T, C = x.size(); z = torch.tanh(self.s(x))
        for t in range(1, T):
            X, Y, Z = z[:, t - 1].chunk(3, -1)
            dz = torch.cat([-(Y + Z), X + self.a * Y, self.b + Z * (X - self.c)], -1)
            z[:, t] = z[:, t] + 0.02 * dz
        return z @ self.s.weight.T

class BifurcationControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.mu = nn.Parameter(torch.zeros(1)); self.w = nn.Linear(C, C)
    def forward(self, x):
        B, T, C = x.size(); reg = torch.tanh(self.mu)
        for t in range(1, T):
            nl = self.w(x[:, t - 1]) * (1.0 + reg) - (x[:, t - 1] ** 3) * reg
            x[:, t] = x[:, t] + 0.1 * nl
        return x

class SwitchedDynamics(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=3):
        super().__init__(); self.f = nn.ModuleList([nn.Linear(C, C) for _ in range(K)]); self.ctrl = nn.Linear(C, K)
    def forward(self, x):
        B, T, C = x.size()
        for t in range(1, T):
            m = torch.softmax(self.ctrl(x[:, t - 1]), -1)
            dx = sum(m[:, k:k+1] * self.f[k](x[:, t - 1]) for k in range(len(self.f)))
            x[:, t] = x[:, t] + 0.1 * dx
        return x

class EchoStateReservoir(nn.Module):
    def __init__(self, C=128, T=128, dim=128, Tmax=64):
        super().__init__(); self.W = nn.Parameter(torch.randn(C, C) * 0.5 / C ** 0.5, requires_grad=False)
    def forward(self, x):
        B, T, C = x.size(); s = torch.tanh(x[:, 0]); out = [s]
        for t in range(1, T):
            s = torch.tanh(x[:, t] + self.W @ s.T).T; out.append(s)
        return torch.stack(out, 1)

class SlidingModeControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.S = nn.Linear(C, C); self.L = nn.Parameter(torch.tensor(0.1))
    def forward(self, x):
        B, T, C = x.size()
        for t in range(1, T):
            e = x[:, t] - x[:, t - 1]; sigma = self.S(e)
            u = -self.L * torch.tanh(sigma / 0.1)
            x[:, t] = x[:, t] + u
        return x

class MPCSim(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=4):
        super().__init__(); self.H = H; self.f = nn.Linear(C, C); self.g = nn.Linear(C, C)
    def forward(self, x):
        B, T, C = x.size(); y = x.clone()
        for t in range(T):
            s = y[:, t]
            for _ in range(self.H): u = torch.tanh(self.g(s)); s = s + self.f(s) + 0.05 * u
            y[:, t] = s
        return y

class ResidualInvertibleFlow(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.w = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1) / n.view(1, -1, 1)
        g = torch.tanh(self.w(ctx)) * 0.3
        return x + g

class DDPMLinearDiffusion(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.eps = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1) / n.view(1, -1, 1)
        a = (torch.arange(x.size(1), device=x.device).float()/x.size(1)).view(1,-1,1)
        return (x - a*self.eps(ctx)) / (1-a+1e-5)

class SDEsVPSDEDiffusion(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.score = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1) / n.view(1, -1, 1)
        b = 0.1
        return x + b*(ctx - x) + b*self.score(ctx)*0.1

class EnergyBasedMixture(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.h = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1) / n.view(1, -1, 1)
        e = (self.h(x)*ctx).sum(-1, keepdim=True)
        return x - 0.1*torch.autograd.grad(e.sum(), x, create_graph=True)[0]

class AmortizedVariationalMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.mu = nn.Linear(C, C); self.lv = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1)/n.view(1,-1,1)
        z = self.mu(ctx) + (0.5*self.lv(ctx)).exp()*torch.randn_like(ctx)
        return x + 0.5*z

class LangevinMCMCMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.h = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1)/n.view(1,-1,1)
        e = (self.h(x)*ctx).sum(-1).sum()
        g = torch.autograd.grad(e, x, create_graph=True)[0]
        return x - 0.05*g + 0.1*torch.randn_like(x)

class BeliefPropagationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.msg = nn.Linear(C, C)
    def forward(self, x):
        left = torch.cat([x[:, :1], x[:, :-1]], 1)
        right = torch.cat([x[:, 1:], x[:, -1:]], 1)
        m = 0.5*(self.msg(left) + self.msg(right))
        return x + 0.3*torch.tanh(m)

class DPPDiversifyMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.A = nn.Linear(C, C)
    def forward(self, x):
        y = self.A(x)
        sim = torch.einsum('btc,bsc->bts', y, y)
        eye = torch.eye(x.size(1), device=x.device).unsqueeze(0)
        return x - 0.1*(sim*eye).permute(0,2,1) @ y

class GaussianCopulaMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.P = nn.Parameter(torch.eye(C)*0.1)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1)/n.view(1,-1,1)
        u = torch.sigmoid((x-ctx).cumsum(1))
        z = torch.erfinv(2*u-1)
        return x + 0.2*(z @ self.P)

class SdmMemory(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n_addr=128, k=32):
        super().__init__()
        self.addr = nn.Parameter(torch.randn(n_addr, C))
        self.val = nn.Parameter(torch.zeros(n_addr, C))
        self.k = k
    def forward(self, x):
        s = torch.einsum('bc,nc->bn', x.mean(1), self.addr)
        w = torch.zeros_like(s).scatter(1, torch.topk(s, self.k, 1).indices, 1.0)
        return x + (w @ self.val)[:, None, :]

class GlobalWorkspace(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=4):
        super().__init__()
        self.compress = nn.Linear(C, K)
        self.broadcast = nn.Linear(K, C)
    def forward(self, x):
        g = self.broadcast(self.compress(x.amax(1)))
        gate = torch.softmax(self.compress(x), -1)
        return x + 0.1 * g[:, None, :] * gate.sum(-1, keepdim=True)

class PredictiveCoding(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.up = nn.Linear(C, C)
    def forward(self, x):
        pred = self.up(x.roll(1, 1))
        err = torch.tanh(x - pred)
        return x + err

class FreeEnergyLayer(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.mu = nn.Linear(C, C)
        self.prec = nn.Parameter(torch.ones(1, 1, C))
    def forward(self, x):
        mu = self.mu(x)
        fe = self.prec * (x - mu) ** 2
        return x - 0.1 * fe * (x - mu)

class HdcBinding(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.rot = nn.Parameter(torch.randn(C, C))
    def forward(self, x):
        perm = x @ self.rot
        return torch.tanh(0.5 * (x + perm))

class LogicTensorNet(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.W = nn.Linear(C, C)
    def forward(self, x):
        sat = torch.sigmoid(self.W(x))
        return x + 0.1 * (sat - x)

class SchemaNet(nn.Module):
    def __init__(self, C=128, T=128, dim=128, R=8):
        super().__init__()
        self.key = nn.Linear(C, R)
        self.val = nn.Linear(R, C)
    def forward(self, x):
        roles = torch.softmax(self.key(x), -1)
        return x + self.val(roles)

class ActRBuffer(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.buf = nn.Parameter(torch.zeros(1, 1, C))
        self.gate = nn.Linear(2 * C, C)
    def forward(self, x):
        ctx = torch.cat([x, self.buf.expand_as(x)], -1)
        g = torch.sigmoid(self.gate(ctx))
        return x + g * self.buf.expand_as(x)

class ProgramStack(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.push = nn.Linear(C, C)
        self.pop = nn.Linear(C, C)
    def forward(self, x):
        return x + 0.1 * (torch.tanh(self.push(x)) - torch.tanh(self.pop(x.roll(1, 1))))

class AnalogicalMap(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.base = nn.Parameter(torch.randn(1, 1, C))
    def forward(self, x):
        sim = torch.cosine_similarity(x, self.base.expand_as(x), -1)
        return x + 0.1 * self.base * sim[..., None]

class TensorProductBinding(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.role = nn.Parameter(torch.randn(64, C))
    def forward(self, x):
        T = x.size(1)
        tp = torch.einsum('btc,tk->btck', x, self.role[:T]).flatten(-2)[:, :, :C]
        return x + 0.1 * tp

class BayesianProgram(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.prior = nn.Parameter(torch.zeros(1, 1, C))
        self.lik = nn.Linear(C, C)
    def forward(self, x):
        post = torch.sigmoid(self.prior + self.lik(x))
        return x + 0.1 * (post - self.prior)

class ChemotaxisMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.W = nn.Parameter(torch.randn(C, C)*0.1)
    def forward(self, x):
        B,T,C = x.shape
        conc = (x @ self.W).sum(-1)
        w = torch.softmax(conc, -1).unsqueeze(1)
        ctx = (w.transpose(1,2) @ x).expand_as(x)
        return x + 0.5*(ctx - x)

class AxonalDelayMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, lags=4):
        super().__init__()
        self.w = nn.Parameter(torch.ones(lags)/lags)
    def forward(self, x):
        s = [torch.roll(x, -k, dims=1) for k in range(len(self.w))]
        out = sum(self.w[k]*s[k] for k in range(len(self.w)))
        return x + 0.5*(out - x)

class DendriticGateMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.dend = nn.Linear(C, C); self.soma = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device).view(1,-1,1)
        ctx = x.cumsum(1)/n
        g = torch.sigmoid(self.dend(ctx))
        return x + 0.5*(g*self.soma(ctx) - x)

class HomeostaticMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, target=0.5):
        super().__init__(); self.target=target; self.s=nn.Parameter(torch.ones(C))
    def forward(self, x):
        gain = self.target/(x.detach().abs().mean()+1e-6)
        mean = x.mean(1, keepdim=True)
        return self.s*(x + 0.3*(mean - x))*gain.clamp(0,2)

class MetaplasticMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Parameter(torch.tensor(0.1)); self.b=nn.Parameter(torch.zeros(C))
    def forward(self, x):
        hist = x.detach().abs().mean((0,1))
        mod = torch.sigmoid(self.b + self.a*hist)
        return x + mod.view(1,1,-1)*(x.roll(1,1) - x)

class GridCellMix(nn.Module):
    def __init__(self, C=128, T=128, periods=(3,5,8)):
        super().__init__(); self.p=periods
    def forward(self, x):  # (B, C, T)
        t = torch.arange(x.size(2), device=x.device).float()  # (T,)
        ph = torch.stack([torch.sin(2*3.14159*t/p) for p in self.p], -1)  # (T, P)
        W = torch.softmax(ph @ ph.transpose(0, 1), -1)  # (T, T) positional mixer
        return x + 0.5*(torch.einsum('ij,bcj->bci', W, x) - x)

class PhasePrecessionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, theta=8):
        super().__init__(); self.theta=theta
    def forward(self, x):
        t = torch.arange(x.size(1), device=x.device).float()
        ph = t/self.theta % 1.0
        W = torch.softmax(torch.cos(2*3.14159*(ph[:,None]-ph[None,:])), -1)
        return x + 0.5*(W[None,:,:] @ x - x)

class VolumeTransmissionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.d=nn.Parameter(torch.tensor(0.3))
    def forward(self, x):
        g = x.mean(1, keepdim=True)
        return x + self.d*(g - x)

class NeuralSheafMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Parameter(torch.tensor(0.3))
    def forward(self, x):
        A = torch.softmax(x @ x.transpose(1,2), -1)
        L = torch.eye(A.size(1), device=x.device) - A
        return x + self.a*(L @ x)

class CircadianMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, period=24):
        super().__init__(); self.p=period; self.g=nn.Parameter(torch.tensor(0.2))
    def forward(self, x):
        t = torch.arange(x.size(1), device=x.device).float()
        osc = 0.5+0.5*torch.sin(2*3.14159*t/self.p)
        return x + (self.g*osc.view(1,-1,1))*(x.roll(1,1) - x)

class AplysiaHabituationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.e=nn.Parameter(torch.tensor(0.1)); self.r=nn.Parameter(torch.zeros(C))
    def forward(self, x):
        sal = x.detach().pow(2).mean((0,1))
        hab = torch.sigmoid(self.r + self.e*sal)
        return x + hab.view(1,1,-1)*(x.roll(1,1) - x)

class SynfireMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Parameter(torch.randn(C,C)*0.1); self.g=nn.Parameter(torch.tensor(0.4))
    def forward(self, x):
        chain = x.roll(1,1) @ self.W
        return x + self.g*chain

class SymplecticLeapfrogMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.q=nn.Linear(C,C); self.p=nn.Linear(C,C); self.dt=nn.Parameter(torch.tensor(0.3))
    def forward(self,x):
        p=torch.tanh(self.p(x)); x=x+self.dt*p; p=p- self.dt*torch.tanh(self.q(x)); return x+self.dt*p

class AdiabaticAnnealMix(nn.Module):
    def __init__(self, C=128, T=64, dim=128):
        super().__init__(); self.W=nn.Parameter(torch.randn(C,C)*0.1); self.s=nn.Parameter(torch.linspace(0,1,T))
    def forward(self,x):
        W=self.W[None]+self.s[:,None,None]*torch.eye(x.size(2),device=x.device)[None]
        return x+0.1*(x@W.mean(0).transpose(-1,-2))

class KacMoodyAffineMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Linear(C,C); self.b=nn.Linear(C,C); self.k=nn.Parameter(torch.tensor(1.0))
    def forward(self,x):
        c=(self.a(x)*self.b(x)).cumsum(1); return x+0.1*(c+self.k*torch.roll(x,1,1))

class CasimirInvariantMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.g=nn.Linear(C,C)
    def forward(self,x):
        q=self.g(x); cas=(q*q).sum(-1,keepdim=True); return x+0.1*torch.tanh(cas)*x

class TopoEdgeStateMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.f=nn.Linear(C,C)
    def forward(self,x):
        e=x[:,[0]]+x[:,[-1]]; e=(e-x[:,[-1]]).expand_as(x); return x+0.1*self.f(e)

class GrossPitaevskiiBecMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.k=nn.Parameter(torch.tensor(1.0)); self.g=nn.Parameter(torch.tensor(0.5))
    def forward(self,x):
        lap=x- torch.roll(x,1,1); return x+0.1*(self.k*lap+self.g*(x.abs()**2)*x)

class LandauDampingPlasmaMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.g=nn.Linear(C,C); self.gamma=nn.Parameter(torch.tensor(0.1))
    def forward(self,x):
        h=torch.fft.rfft(self.g(x),dim=1); return x+0.1*torch.fft.irfft(h/(1+self.gamma*torch.arange(h.size(1),device=x.device)[None,None,:]),dim=1,n=x.size(1))

class ElastodynamicWaveMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.c=nn.Parameter(torch.tensor(1.0)); self.m=nn.Parameter(torch.tensor(0.05)); self.v=nn.Parameter(torch.zeros(1,C))
    def forward(self,x):
        lap=x-torch.roll(x,1,1)-torch.roll(x,-1,1)+x; a=self.c*2*lap-self.m*self.v; self.v.data=self.v+0.1*a.mean(0,keepdim=True); return x+a

class FresnelThinFilmMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.phase=nn.Parameter(torch.randn(C)); self.z=nn.Parameter(torch.tensor(1.0))
    def forward(self,x):
        H=torch.exp(-1j*(self.phase**2)*self.z); return x*0 + torch.real(torch.fft.irfft(torch.fft.rfft(x,dim=1)*H[None,None,:],dim=1,n=x.size(1)))

class AcousticWaveguideMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.U=nn.Parameter(torch.eye(C)); self.V=nn.Parameter(torch.eye(C)); self.beta=nn.Parameter(torch.rand(C))
    def forward(self,x):
        y=x@self.U; y=y*self.beta[None,None,:]; return y@self.V

class PerronFrobeniusBrownianMix(nn.Module):
    def __init__(self, C=128, T=64, dim=128):
        super().__init__(); self.M=nn.Parameter(torch.rand(T,T)); 
    def forward(self,x):
        P=torch.softmax(self.M,dim=1); return x@P.t()

class KpzUniversalityMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.nu=nn.Parameter(torch.tensor(1.0)); self.lam=nn.Parameter(torch.tensor(0.5))
    def forward(self,x):
        g=x-torch.roll(x,1,1); return x+0.1*(self.nu*2*(x-torch.roll(x,1,1)-torch.roll(x,-1,1)+x)+self.lam*g**2)

class MobiusMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.a=nn.Parameter(torch.randn(C)+1j); self.b=nn.Parameter(torch.randn(C)+1j); self.c=nn.Parameter(torch.randn(C)+1j); self.d=nn.Parameter(torch.randn(C)+1j)
  def forward(self,x):
    z=x.to(torch.cfloat); return ((self.a*z+self.b)/(self.c*z+self.d)).real.float()

class ModularFormMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.k=nn.Parameter(torch.randn(C)*0.1); self.q=0.97
  def forward(self,x):
    T=x.shape[1]; n=torch.arange(T).float(); w=torch.exp(1j*torch.pi*self.k.unsqueeze(1)*n).real
    return x*w.unsqueeze(0).transpose(1,2)

class QuaternionMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.C=C//4; self.w=nn.Parameter(torch.randn(self.C,4,4)*0.1)
  def forward(self,x):
    x=x.view(*x.shape[:-1],self.C,4); y=(x.unsqueeze(-2)*self.w).sum(-1); return y.view(*x.shape[:-2],self.C*4)

class OctonionMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.C=C//8; self.w=nn.Parameter(torch.randn(self.C,8,8)*0.1)
  def forward(self,x):
    x=x.view(*x.shape[:-1],self.C,8); y=(x.unsqueeze(-2)*self.w).sum(-1); return y.view(*x.shape[:-2],self.C*8)

class LieCommutatorMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.A=nn.Linear(C,C); self.B=nn.Linear(C,C)
  def forward(self,x):
    a=self.A(x); b=self.B(x); return x+0.1*(torch.einsum('bti,btj->btj',a,b)-torch.einsum('bti,btj->btj',b,a))

class TeichmullerMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.mu=nn.Parameter(torch.randn(C)*0.1)
  def forward(self,x):
    z=x.to(torch.cfloat); w=(1+torch.tanh(self.mu)).unsqueeze(0); return (z+w*(z.conj()*self.mu).unsqueeze(0)).real.float()

class DeRhamMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.a=nn.Parameter(torch.ones(C)*0.1)
  def forward(self,x):
    d=x[...,1:,:]-x[...,:-1,:]; lap=torch.cat([d[...,:1,:],d[...,1:,:]-d[...,:-1,:],-d[...,-1:,:]],-2); return x-self.a*0.1*lap

class MorseMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.f=nn.Linear(C,1)
  def forward(self,x):
    p=torch.sigmoid(self.f(x)); g=torch.sigmoid(self.f(x.roll(1,1))); return x*(1+0.2*(p-g))

class CatastropheMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.a=nn.Parameter(torch.zeros(C)); self.b=nn.Parameter(torch.zeros(C))
  def forward(self,x):
    u=x.mean(-1,keepdim=True); return x+0.1*(u**3+self.a*u+self.b)*torch.sign(x)+0.0

class MatroidMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.w = nn.Linear(C, C)
    def forward(self, x):  # (B, C, T)
        s_ = torch.softmax(self.w(x), -1)
        top, _ = torch.topk(s_, max(2, x.shape[-1] // 2), -1)
        m = torch.zeros_like(s_).scatter_(-1, top, 1)
        return x * m

class TropicalValuationMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.w=nn.Parameter(torch.randn(C,C)*0.1)
  def forward(self,x):
    proj=torch.einsum('ij,btj->bti',self.w,x); return x+0.1*(torch.max(proj,-1,keepdim=True).values-proj.mean(-1,keepdim=True))

class GaloisConnectionMix(nn.Module):
  def __init__(self, C=128, T=128, dim=128):
    super().__init__(); self.up=nn.Linear(C,C); self.down=nn.Linear(C,C)
  def forward(self,x):
    f=torch.relu(self.up(x)); g=torch.relu(self.down(f)); return x+0.1*(g-x)

class SparseDistributedMemoryMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=64):
        super().__init__(); self.M=M
        self.hard = nn.Linear(C, M, bias=False); self.read = nn.Linear(M, C, bias=False)
    def forward(self, x):
        a = (self.hard(x) > 0).float()
        return x + 0.1*self.read(a)

class CompressiveSensingRIPMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.P = nn.Parameter(torch.randn(T//2, T)/T**0.5)
        self.w = nn.Linear((T//2)*C, T*C, bias=False)
    def forward(self, x):
        B,T,C = x.shape
        y = (x @ self.P.t()).reshape(B,-1)
        return self.w(y).reshape(B,T,C) + x

class LempelZivComplexityMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.est = nn.Conv1d(C, C, 3, padding=1, groups=C)
        self.gate = nn.Sequential(nn.Linear(C,1), nn.Sigmoid())
    def forward(self, x):
        c = self.est(x.transpose(1,2)).transpose(1,2)
        return x*(1-self.gate(c)) + c*self.gate(c)

class BitsBackCodingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.prior = nn.Linear(C, 2*C); self.upd = nn.Linear(2*C, C)
    def forward(self, x):
        mu, logb = self.prior(x).chunk(2, -1)
        z = (x-mu)*torch.exp(-logb)
        return x + 0.1*self.upd(torch.cat([mu, z], -1))

class PredictiveCodingFreeEnergyMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.pred = nn.Linear(C, C); self.tau = nn.Parameter(torch.ones(1)*0.5)
    def forward(self, x):
        err = x - self.pred(x)
        return x - self.tau*err

class FisherInformationGeometryMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.G = nn.Parameter(torch.eye(C)); self.delta = nn.Linear(C, C)
    def forward(self, x):
        g = torch.softmax(self.G, -1)
        return x - 0.1*(self.delta(x) @ g)

class OptimalTransportCodesMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=16):
        super().__init__(); self.code = nn.Parameter(torch.randn(K, C)); self.reg=0.1
    def forward(self, x):
        sim = torch.einsum('btc,kc->btk', x, self.code)
        P = torch.softmax(sim/self.reg, -1)
        return torch.einsum('btk,kc->btc', P, self.code)

class ResidueArithmeticMix(nn.Module):
    def __init__(self, C=128, T=128, mods=(3,5,7,11)):
        super().__init__(); self.mods=mods; self.proj=nn.Linear(C, C)
    def forward(self, x):  # (B, C, T)
        y = self.proj(x.transpose(1, 2)).transpose(1, 2)  # project on channel dim
        r = torch.stack([y % m for m in self.mods], -1).mean(-1)
        return x + 0.1*r

class QuasiCycleCodesMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.T=T; self.gen=nn.Parameter(torch.randn(C,C)/C**0.5)
    def forward(self, x):
        out = torch.zeros_like(x)
        for s in range(min(4, self.T)):
            out += torch.roll(x, s, 1) @ self.gen
        return x + 0.1*out

class GolayPerfectCodesMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C, C))/C**0.5
        self.proj = nn.Linear(C, 12, bias=False); self.exp = nn.Linear(12, C, bias=False)
    def forward(self, x):
        c = self.proj(x)  # compress to 12-dim perfect-code core
        return x + 0.1*self.exp(c)

class BeliefPropagationTrellisMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, iters=3):
        super().__init__(); self.iters=iters; self.msg=nn.Linear(2*C, C)
    def forward(self, x):
        h = x
        for _ in range(self.iters):
            l = torch.cat([torch.roll(h,1,1), torch.roll(h,-1,1)], -1)
            h = x + self.msg(l)
        return h

class SourceCodingArithmeticBPMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.cdf = nn.Sequential(nn.Linear(C,C), nn.Softmax(-1))
    def forward(self, x):
        w = self.cdf(x)
        return x + 0.1*torch.einsum('btc,btc->btc', x, w)

class MelCepstralMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, nf=32, nd=16):
        super().__init__(); self.lin=nn.Linear(C,nf); self.cep=nn.Linear(nf,nd); self.out=nn.Linear(nd,C)
    def forward(self,x):
        m=torch.log1p(torch.relu(self.lin(x)).pow(2)); c=self.cep(m); return self.out(c)

class ConstantQMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, bins=24, oct=4, k=33):
        super().__init__(); self.W=nn.Parameter(torch.randn(bins,C,k)*0.1); self.proj=nn.Linear(bins,C)
    def forward(self,x):
        B,T,C=x.shape; xw=(x.unfold(1,self.W.shape[2],1)*self.W).sum(-1); return self.proj(xw.transpose(-1,-2))

class SynchrosqueezeMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, sc=8):
        super().__init__(); self.psi=nn.Parameter(torch.randn(sc,C,15)*0.1); self.out=nn.Linear(C,C)
    def forward(self,x):
        w=(x.unfold(1,15,1)*self.psi).sum(-1); a=torch.angle(torch.fft.hfft(w,dim=-2)); return self.out(w*torch.exp(-1j*a).real)

class STransformMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=32):
        super().__init__(); self.f=nn.Parameter(torch.linspace(1,16,K)); self.out=nn.Linear(K,C)
    def forward(self,x):
        t=torch.arange(x.shape[1]).float(); g=torch.exp(-(t[None,:]-t[:,None]).pow(2)/(2*self.f[:,None,None]**2)); return self.out((x[None]*g).sum(-1).transpose(-1,-2))

class MatchingPursuitMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, A=32, k=17, it=4):
        super().__init__(); self.atoms=nn.Parameter(torch.randn(A,C,k)); self.it=it; self.out=nn.Linear(A,C)
    def forward(self,x):
        r=x.clone(); c=[]
        for _ in range(self.it):
            sc=(r.unfold(1,k,1)*self.atoms).sum(-1); i=sc.argmax(1,keepdim=True); c.append(torch.gather(sc,1,i)); 
        return self.out(torch.stack(c,2).sum(2))

class EmpiricalModeMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, m=6):
        super().__init__(); self.m=m; self.w=nn.Parameter(torch.ones(m,C,1)); self.out=nn.Linear(m,C)
    def forward(self,x):
        env=x.unsqueeze(1).repeat(1,self.m,1,1).mean(2,keepdim=True); imf=x-self.w*env; return self.out(imf.mean(2).transpose(-1,-2))

class HigherOrderWignerMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, L=8):
        super().__init__(); self.L=L; self.out=nn.Linear(2*L-1,C)
    def forward(self,x):
        z=x.float(); c=torch.einsum('btc,bjc->btj',z,z); w=c.unfold(1,self.L,1).mean(-1); return self.out(w.transpose(-1,-2))

class ChirpZMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=32):
        super().__init__(); self.M=M; self.phi=nn.Parameter(torch.linspace(0,1,M)); self.out=nn.Linear(M,C)
    def forward(self,x):
        n=torch.arange(x.shape[1]).float(); A=torch.exp(2j*3.14159*self.phi[:,None]*n[None,:]); return self.out((x[None]*A).sum(-1).real.transpose(-1,-2))

class BispectrumMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, W=11):
        super().__init__(); self.W=W; self.out=nn.Linear(W*W//2,C)
    def forward(self,x):
        w=x.unfold(1,self.W,1); b=torch.einsum('btkc,btjc->btkj',w,w).mean(-1); return self.out(b.flatten(-2))

class FractionalHilbertMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Parameter(torch.zeros(C)); self.out=nn.Linear(2*C,C)
    def forward(self,x):
        H=torch.fft.hfft(x,dim=1).imag; r=torch.cos(self.a); i=torch.sin(self.a); m=r*x+i*H; return self.out(torch.cat([m,H],-1))

class ShearletMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, sh=4, sc=3):
        super().__init__(); self.k=nn.Parameter(torch.randn(sh,sc,C,9)); self.out=nn.Linear(sh*sc,C)
    def forward(self,x):
        u=x.unfold(1,9,1); m=(u*self.k).sum(-1); return self.out(m.flatten(-2))

class EmpiricalWaveletMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, nb=8):
        super().__init__(); self.edge=nn.Parameter(torch.sort(torch.rand(nb)).values); self.out=nn.Linear(nb,C)
    def forward(self,x):
        f=torch.fft.fftfreq(x.shape[1]).to(x); m=(f.unsqueeze(0)-self.edge.unsqueeze(1)).abs().min(0).values; return self.out((x*torch.sigmoid(-m)[None,:,None]).transpose(-1,-2))

class HopfBifurcationOscillator(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; h=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            r2=(h*h).sum(-1,keepdim=True); h=h+0.1*((0.1-r2)*h+self.fc(x[:,t])); out.append(h)
        return torch.stack(out,1)

class VanDerPolOscillator(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; h=torch.zeros(B,C,device=x.device); v=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            dv=0.5*(1-h*h)*v-h+self.fc(x[:,t]); dh=v; h,v=h+0.1*dh,v+0.1*dv; out.append(h)
        return torch.stack(out,1)

class FitzHughNagumo(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; v=torch.zeros(B,C,device=x.device); w=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            dv=v-v**3/3-w+self.fc(x[:,t]); dw=0.08*(v+0.7-1.25*w); v,w=v+0.1*dv,w+0.1*dw; out.append(v)
        return torch.stack(out,1)

class ChuaCircuit(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; v=torch.zeros(B,C,device=x.device); w=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            g=0.1*w+0.5*(torch.abs(w+1)-torch.abs(w-1)); dv=0.1*(w-v-g); dw=v-w+g+self.fc(x[:,t]); v,w=v+0.1*dv,w+0.1*dw; out.append(v)
        return torch.stack(out,1)

class DuffingOscillator(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; y=torch.zeros(B,C,device=x.device); z=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            dz=-0.3*z-0.5*y-y**3+self.fc(x[:,t]); dy=z; y,z=y+0.1*dy,z+0.1*dz; out.append(y)
        return torch.stack(out,1)

class ImpedanceControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.k=nn.Parameter(torch.ones(C)); self.d=nn.Parameter(0.1*torch.ones(C))
    def forward(self,x):
        B,T,C=x.shape; q=torch.zeros(B,C,device=x.device); qd=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            f=(x[:,t]-q)*self.k-qd*self.d; qd=qd-0.1*f; q=q+0.1*qd; out.append(q)
        return torch.stack(out,1)

class AdaptiveControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.w=nn.Parameter(torch.zeros(C)); self.fc=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; y=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            e=x[:,t]-y; self.w.data.add_(0.01*e.mean(0)); y=self.fc(y)+self.w*x[:,t]; out.append(y)
        return torch.stack(out,1)

class BacksteppingControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a1=nn.Linear(C,C); self.a2=nn.Linear(C,C); self.c=nn.Parameter(torch.tensor(1.0))
    def forward(self,x):
        B,T,C=x.shape; z1=torch.zeros(B,C,device=x.device); z2=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            v=-self.c*z1-self.a1(z1); z2=z2-self.a2(z2)+v; z1=z1+0.1*z2; out.append(z1)
        return torch.stack(out,1)

class PontryaginOptimalControl(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.f=nn.Linear(C,C); self.l=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape; lam=torch.zeros(B,C,device=x.device); y=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            u=-0.5*lam; y=y+0.1*(self.f(y)+u); lam=lam-0.1*self.l(y); out.append(y)
        return torch.stack(out,1)

class CPGChain(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.w=nn.Parameter(torch.eye(C)*0.3)
    def forward(self,x):
        B,T,C=x.shape; s=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            s=s+0.1*(torch.tanh(self.w@s.unsqueeze(-1)).squeeze(-1)+x[:,t]); out.append(s)
        return torch.stack(out,1)

class StochasticResonance(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.k=nn.Parameter(torch.tensor(0.3))
    def forward(self,x):
        B,T,C=x.shape; s=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            n=torch.randn_like(x[:,t])*self.k; s=0.9*s+torch.tanh(x[:,t]+n); out.append(s)
        return torch.stack(out,1)

class LimitCycleEntrainment(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C); self.omega=nn.Parameter(torch.ones(C)*0.2)
    def forward(self,x):
        B,T,C=x.shape; p=torch.zeros(B,C,device=x.device); out=[]
        for t in range(T):
            p=p+self.omega+0.3*torch.sin(self.fc(x[:,t])-p); out.append(torch.sin(p))
        return torch.stack(out,1)

class HamiltonianMCMCMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, steps=3):
        super().__init__(); self.steps=steps
        self.grad=nn.Linear(C,C); self.mass=nn.Parameter(torch.ones(C))
    def forward(self, x):
        p=torch.randn_like(x)*self.mass
        for _ in range(self.steps):
            p=p-0.5*self.grad(x); x=x+self.mass*p; p=p-0.5*self.grad(x)
        return x

class FFJORDContinuousFlow(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.net=nn.Linear(C,C)
    def forward(self, x):
        eps=torch.randn_like(x)
        trace=(eps*(eps@self.net.weight.t())).sum(-1,keepdim=True)
        return x+self.net(x)*0.1-trace*0.01

class VAEBottleneckMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=32):
        super().__init__(); self.e=nn.Linear(C,K); self.d=nn.Linear(K,C)
    def forward(self, x):
        mu=self.e(x); z=mu+torch.randn_like(mu)
        return x+self.d(z)-self.d(mu)

class BoltzmannMachineMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Parameter(torch.randn(C,C)*0.1)
    def forward(self, x):
        h=torch.sigmoid(x@self.W.t()+x@self.W)
        return torch.sigmoid(h@self.W+x@self.W.t())

class WakeSleepMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.q=nn.Linear(C,C); self.r=nn.Linear(C,C)
    def forward(self, x):
        z=torch.tanh(self.q(x)); rec=torch.tanh(self.r(z))
        return x+0.1*(rec-x)

class HelmholtzMachineMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=32):
        super().__init__(); self.bot=nn.Linear(C,K); self.top=nn.Linear(K,C)
    def forward(self, x):
        h=torch.sigmoid(self.bot(x)); return x+self.top(h)

class DenoisingScoreMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.s=nn.Linear(C,C)
    def forward(self, x):
        n=x+0.1*torch.randn_like(x); return x+self.s(n-x)

class AdversarialSelfsupMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.g=nn.Linear(C,C); self.disc=nn.Linear(C,1)
    def forward(self, x):
        gx=self.g(x); fake=torch.sigmoid(self.disc(gx))
        return x+self.g(x)*(1-fake.detach())

class DirichletProcessMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=64):
        super().__init__(); self.mu=nn.Parameter(torch.randn(K,C)); self.a=nn.Parameter(torch.ones(1))
    def forward(self, x):
        w=torch.softmax(-((x[:,:,None,:]-self.mu)/self.a).pow(2).sum(-1),-1)
        return w@self.mu

class ThompsonSamplingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.mean=nn.Parameter(torch.zeros(C)); self.logvar=nn.Parameter(torch.zeros(C))
    def forward(self, x):
        s=self.mean+torch.exp(0.5*self.logvar)*torch.randn_like(x)
        return x+s.unsqueeze(1)

class VariationalDropoutMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.w=nn.Parameter(torch.zeros(C)); self.d=nn.Linear(C,C)
    def forward(self, x):
        m=torch.sigmoid(self.w); return self.d(x)*m

class StochasticGradientLangevin(nn.Module):
    def __init__(self, C=128, T=128, dim=128, lr=0.01):
        super().__init__(); self.net=nn.Linear(C,C); self.lr=lr; self.register_buffer('t',torch.tensor(1.))
    def forward(self, x):
        self.t+=1; n=torch.sqrt(torch.tensor(self.lr/self.t))*torch.randn_like(x)
        return self.net(x)+n

class PointerNet(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.q=nn.Linear(C,C)
    def forward(self,x):
        B,T,C=x.shape
        s=(self.q(x)@x.transpose(1,2))/C**0.5
        return s.softmax(-1)@x

class VSABinding(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.key=nn.Parameter(torch.randn(C))
    def forward(self,x):
        X=torch.fft.rfft(x,dim=-1); K=torch.fft.rfft(self.key)
        return torch.fft.irfft(X*K.unsqueeze(1),n=x.size(-1),dim=-1)

class SemanticPointer(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.bind=nn.Linear(C,C)
    def forward(self,x):
        bound=x@self.bind.weight.t()
        return torch.tanh(bound)

class HTMColumn(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=32): super().__init__(); self.k=k; self.fc=nn.Linear(C,C)
    def forward(self,x):
        z=self.fc(x); k=min(self.k,z.size(-1))
        thr=z.kthvalue(z.size(-1)-k+1,dim=-1).values.unsqueeze(-1)
        return z*(z>=thr)

class ARTResonance(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.proto=nn.Parameter(torch.randn(C))
    def forward(self,x):
        sim=F.cosine_similarity(x,self.proto,dim=-1,eps=1e-8).unsqueeze(-1)
        return x*torch.sigmoid((sim-0.5)*10)

class SchemaRetrieval(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=8): super().__init__(); self.slot=nn.Parameter(torch.randn(n,C))
    def forward(self,x):
        w=torch.einsum('btc,nc->btn',x,self.slot).softmax(-1)
        return x+torch.einsum('btn,nc->btc',w,self.slot)

class MetacognitiveGate(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.est=nn.Linear(C,1); self.upd=nn.Linear(C,C)
    def forward(self,x):
        c=torch.sigmoid(self.est(x))
        return x*(1-c)+self.upd(x)*c

class WMGating(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.register_buffer('ctx',torch.zeros(1,C)); self.wr=nn.Linear(C,1); self.ww=nn.Linear(C,1)
    def forward(self,x):
        wg=torch.sigmoid(self.ww(x)); rg=torch.sigmoid(self.wr(x))
        ctx=self.ctx*(1-wg.mean(1,keepdim=True))+x.mean(1,keepdim=True)*wg.mean(1,keepdim=True)
        self.ctx=ctx.detach(); return x+rg*ctx

class EpisodicBuffer(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=16): super().__init__(); self.slots=nn.Parameter(torch.randn(n,C))
    def forward(self,x):
        s=torch.einsum('btc,nc->btn',x,self.slots)
        return x+torch.einsum('btn,nc->btc',s.softmax(-1),self.slots)

class CognitiveMap(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.grid=nn.Parameter(torch.randn(C,C))
    def forward(self,x):
        P=self.grid@self.grid.t()
        return torch.tanh(x@P+x)

class LiquidState(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.W=nn.Parameter(torch.randn(C,C)/C**0.5); self.a=nn.Linear(C,C)
    def forward(self,x):
        h=torch.zeros_like(x[:,0])
        for t in range(x.size(1)):
            h=torch.tanh(h@self.W+x[:,t]); x=x.clone(); x[:,t]=x[:,t]+self.a(h)
        return x

class ComplementaryLearning(nn.Module):
    def __init__(self, C=128, T=128, dim=128): super().__init__(); self.fast=nn.Linear(C,C); self.slow=nn.Linear(C,C)
    def forward(self,x):
        return x+0.3*self.fast(x)+0.7*self.slow(x).detach()

class RetinotopicMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=3):
        super().__init__(); self.k=k
        self.w=nn.Parameter(torch.ones(k,k)/k**2)
    def forward(self,x):
        B,T,C=x.shape; s=int(math.ceil(T**0.5))
        g=torch.zeros(B,s*s,C,device=x.device); g[:, :T]=x
        g=g.view(B,s,s,C).permute(0,3,1,2)
        out=F.conv2d(g,self.w.expand(C,1,self.k,self.k).clone().unsqueeze(1),groups=C,padding=self.k//2)
        return out.permute(0,2,3,1).reshape(B,s*s,C)[:,:T]

class ShuntingInhibitionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.a=nn.Parameter(torch.ones(C)); self.b=nn.Parameter(torch.ones(C))
    def forward(self,x):
        ex=x.exp(); aff=torch.softmax(x,1)
        denom=self.b[None,None,:]+(aff*ex).sum(1,keepdim=True)
        return self.a[None,None,:]*ex/denom

class STDPTdRewardMix(nn.Module):
    def __init__(self, C=128, T=512, dim=128, tau=8.0):
        super().__init__(); self.tau=tau; self.d=nn.Parameter(torch.tensor(1.0))
        self.W=nn.Parameter(torch.randn(C,C)*0.02)
    def forward(self,x):
        t=torch.arange(x.size(1),device=x.device).float()
        g=torch.triu(torch.exp(-(t[None,:]-t[:,None]).clamp(min=0)/self.tau))*self.d
        ctx=(g@x)/(g.sum(1,keepdim=True)+1e-6)
        return x+ctx@self.W

class MorphologicalCompMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=3):
        super().__init__(); self.k=k; self.p=nn.Linear(C,C)
    def forward(self,x):
        xp=F.pad(x,(0,0,self.k//2,self.k//2),'reflect')
        u=xp.unfold(1,self.k,1)
        return self.p((torch.max(u,2)[0]+torch.min(u,2)[0])/2)

class QuorumCollapseMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.gain=nn.Parameter(torch.ones(1)); self.thr=nn.Parameter(torch.zeros(1))
    def forward(self,x):
        pop=x.mean(1,keepdim=True)
        collapse=torch.sigmoid(self.gain*(pop-self.thr))
        return x*(1-collapse)+pop*collapse

class MyelinationGateMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, step=4):
        super().__init__(); self.s=step; self.m=nn.Parameter(torch.tensor(1.0)); self.g=nn.Linear(C,C)
    def forward(self,x):
        long=self.g(x.roll(self.s,1))
        return x+self.m*long

class GlialBufferMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.D=nn.Parameter(torch.tensor(0.3)); self.p=nn.Linear(C,C)
    def forward(self,x):
        lap=x.roll(1,1)+x.roll(-1,1)-2*x
        return self.p(x+self.D*lap)

class NeuralAvalancheMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.s=nn.Parameter(torch.tensor(0.0)); self.p=nn.Linear(C,C)
    def forward(self,x):
        thr=x.var(1,keepdim=True).sqrt()+self.s
        spread=(x.abs()>thr).float()*x.roll(1,1)
        return self.p(x+spread)

class OscillatorDeathMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.k=nn.Parameter(torch.tensor(0.5)); self.p=nn.Linear(C,C)
    def forward(self,x):
        mean=x.mean(1,keepdim=True); lap=x.roll(1,1)+x.roll(-1,1)-2*x
        return self.p(x+self.k*mean+0.1*lap)

class CPGEtraintMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, period=8):
        super().__init__(); self.p=period; self.r=nn.Parameter(torch.randn(C)); self.proj=nn.Linear(C,C)
    def forward(self,x):
        ph=torch.arange(x.size(1),device=x.device)%self.p
        mask=torch.sigmoid(self.r[None,:]*ph[:,None].float())
        return self.proj(x*mask+x.roll(1,1)*(1-mask))

class ImmuneNegSelMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=8):
        super().__init__(); self.det=nn.Parameter(torch.randn(n,C)); self.proj=nn.Linear(C,C)
    def forward(self,x):
        d=(x[:,:,None,:]-self.det[None,None]).pow(2).mean(-1).min(-1,keepdim=True)[0]
        nov=torch.sigmoid(2-d)
        return self.proj(x*nov+x.roll(1,1)*(1-nov))

class EpigeneticSilenceMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.state=nn.Parameter(torch.ones(C)); self.proj=nn.Linear(C,C)
    def forward(self,x):
        sil=torch.sigmoid(-self.state)[None,None,:]
        return self.proj(x.roll(1,1)*sil+x*(1-sil))

class FermiAccelMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=8):
        super().__init__()
        self.k = nn.Parameter(torch.randn(K,C)/C**0.5)
        self.proj = nn.Linear(C,C)
    def forward(self, x):
        T = x.shape[1]
        kick = torch.einsum('kc,t->tkc', self.k, torch.linspace(-1,1,T,device=x.device)).tanh()
        return x + 0.3*self.proj(x*(1+kick))

class AndersonLocalMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, Tmax=256):
        super().__init__()
        self.disorder = nn.Parameter(torch.randn(Tmax,C)*0.1)
    def forward(self, x):
        T = x.shape[1]
        d = self.disorder[:T].unsqueeze(0)
        gate = torch.sigmoid(-d.abs())
        return x*gate + (1-gate)*x.mean(1,keepdim=True)

class HawkingRadMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.beta = nn.Parameter(torch.ones(1))
        self.proj = nn.Linear(C,C)
    def forward(self, x):
        w = torch.linspace(0,1,x.shape[1],device=x.device)
        temp = torch.sigmoid(self.beta)*(1-w)
        return x + self.proj(x)*temp.unsqueeze(-1)

class NoetherConsMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.q = nn.Parameter(torch.randn(C))
        self.proj = nn.Linear(C,C)
    def forward(self, x):
        charge = (x*self.q).sum(-1,keepdim=True)
        return x + self.proj(x - charge*self.q)

class ChernSimonsMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.theta = nn.Parameter(torch.randn(C,C))
        self.proj = nn.Linear(C,C)
    def forward(self, x):
        A = self.theta - self.theta.t()
        chiral = torch.einsum('ij,btj->bti', A, x)
        return x + self.proj(chiral)

class PhononicBandgapMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, fc=0.3):
        super().__init__()
        self.fc = fc; self.proj = nn.Linear(C,C)
    def forward(self, x):
        X = torch.fft.rfft(x.float(),dim=1)
        f = torch.linspace(0,0.5,X.shape[1],device=x.device)
        X[:, (f>self.fc)&(f<2*self.fc)] *= 0.1
        return x + self.proj(torch.fft.irfft(X,n=x.shape[1],dim=1).to(x.dtype))

class MHDMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.v = nn.Linear(C,C); self.b = nn.Linear(C,C)
    def forward(self, x):
        v = self.v(x); b = self.b(x)
        force = v*torch.roll(b,1,1) - b*torch.roll(v,1,1)
        return x + 0.1*force

class RelAberrMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.beta = nn.Parameter(torch.zeros(1)); self.proj = nn.Linear(C,C)
    def forward(self, x):
        mu = torch.linspace(-1,1,x.shape[1],device=x.device)
        dop = (1+self.beta*mu).clamp(min=0.1)
        return x + self.proj(x)*dop.unsqueeze(-1)

class CasimirMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.proj = nn.Linear(C,C)
    def forward(self, x):
        T = x.shape[1]; d = torch.arange(T,device=x.device).float()
        pull = (1.0/(1+(d[None,:]-d[:,None]).abs())).unsqueeze(0)/T
        return x + self.proj((pull@x) - x)

class RamanMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.shift = nn.Parameter(torch.randn(C)*0.1); self.proj = nn.Linear(C,C)
    def forward(self, x):
        w = torch.sigmoid(self.shift.abs())
        s = x + self.shift; a = x - self.shift
        return x + self.proj(w*s + (1-w)*a)

class SpinGlassMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.J = nn.Parameter(torch.randn(C,C)); self.proj = nn.Linear(C,C)
    def forward(self, x):
        inter = torch.einsum('ij,btj->bti', self.J, x)
        fr = inter*torch.tanh(x.sum(1,keepdim=True))
        return x + 0.1*self.proj(fr)

class ReplicaSymMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, R=4):
        super().__init__(); self.R=R; self.proj=nn.Linear(C,C)
    def forward(self, x):
        B,T,C = x.shape
        rep = (x.repeat(self.R,1,1) + 0.05*torch.randn_like(x.repeat(self.R,1,1)))
        avg = rep.view(self.R,B,T,C).mean(0)
        return x + self.proj(avg - x)

class HopfFibrationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C,bias=False); self.P=nn.Linear(C,C)
    def forward(self,x):
        z=torch.tanh(self.W(x))
        base=nn.functional.normalize(self.P(z),dim=-1)
        A=base@base.transpose(1,2); A=A/A.abs().max(-1,True).values.clamp(1e-6)
        return x+0.1*torch.tanh(A@z)

class OrbifoldQuotientMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, g=4):
        super().__init__(); self.g=g; self.W=nn.Linear(C,C)
    def forward(self,x):
        T=x.size(1); y=x.clone()
        for k in range(1,self.g):
            idx=(torch.arange(T)//(T//self.g))*self.g+k-1
            y=y+x[:,idx.clamp(0,T-1)]
        return x+torch.tanh(self.W(y/self.g))

class PerverseSheafMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C); self.t=nn.Parameter(torch.tensor(0.0))
    def forward(self,x):
        mask=(x.abs().mean(-1,keepdim=True)>self.t).float()
        z=self.W(x*mask)
        return x+0.1*torch.tanh(z*mask)

class SymplecticFormMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.J=nn.Parameter(torch.randn(C,C)); self.W=nn.Linear(C,C)
    def forward(self,x):
        J=self.J-self.J.t()
        g=x@J.t()
        return x+0.1*torch.tanh(self.W(g))

class CalabiYauModuliMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.M=nn.Parameter(torch.randn(C,C)); self.W=nn.Linear(C,C)
    def forward(self,x):
        H=(self.M+self.M.t())/2
        return x+0.1*torch.tanh(self.W(x@H))

class JonesPolynomialMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.R=nn.Parameter(torch.randn(C,C)); self.W=nn.Linear(C,C)
    def forward(self,x):
        R=self.R+self.R.t()
        S=torch.softmax((x@R@x.transpose(1,2))/x.size(-1)**0.5,-1)
        return x+0.1*torch.tanh(self.W(S@x))

class SpectralGraphMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C)
    def forward(self,x):
        A=torch.softmax(x@x.transpose(1,2),-1)
        D=(A.sum(-1)+1e-6).pow(-0.5)
        L=torch.eye(A.size(-1),device=x.device)-D[:,None]*A*D[:,:,None]
        return x+0.1*torch.tanh(self.W(x@L))

class HodgeDecompositionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C)
    def forward(self,x):
        G=x-torch.roll(x,1,1)
        curl=torch.roll(G,-1,1)-G
        return x+0.1*torch.tanh(self.W(curl))

class AlexanderDualityMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C)
    def forward(self,x):
        T=x.size(1); idx=(T-1-torch.arange(T,device=x.device))%T
        return x+0.1*torch.tanh(self.W(x[:,idx]))

class ChernClassMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.A=nn.Parameter(torch.randn(C,C)); self.W=nn.Linear(C,C)
    def forward(self,x):
        F=self.A-self.A.t()
        cur=x@F@x.transpose(1,2)
        S=torch.softmax(cur,-1)
        return x+0.1*torch.tanh(self.W(S@x))

class ModuliCurvesMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C); self.s=nn.Parameter(torch.tensor(1.0))
    def forward(self,x):
        s=int(self.s.clamp(1,max(1,x.size(1)//2)))
        return x+0.1*torch.tanh(self.W(x+torch.roll(x,s,1)+torch.roll(x,-s,1)))

class LanglandsCorrespondenceMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W=nn.Linear(C,C)
    def forward(self,x):
        X=torch.fft.fft(x.float(),dim=1).real.to(x.dtype)
        return x+0.1*torch.tanh(self.W(X))

class ChannelCapacityMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, snr=6.0):
        super().__init__()
        self.fc = nn.Linear(C, C)
        self.snr = snr
    def forward(self, x):
        h = self.fc(x)
        n = torch.randn_like(h) * (h.std() / (10**(self.snr/10))**.5)
        return x + 0.1*(h + n - x)

class FountainRaptorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=8):
        super().__init__()
        self.k = k; self.proj = nn.Linear(C, C)
    def forward(self, x):
        idx = torch.randperm(x.shape[1], device=x.device)[:self.k]
        seed = x[:, idx].mean(1, keepdim=True)
        return x + self.proj(seed.expand(-1, x.shape[1], -1))

class PolarListDecodeMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, L=4):
        super().__init__(); self.L = L; self.score = nn.Linear(C, C)
    def forward(self, x):
        s = self.score(x)
        vals, _ = torch.topk(s, self.L, dim=-1)
        a = torch.softmax(vals, -1)
        out = (a.unsqueeze(-1) * vals.unsqueeze(-1)).sum(-2)
        return x + 0.1*out

class ConstellationModulationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=16):
        super().__init__()
        self.sym = nn.Parameter(torch.randn(M, C))
    def forward(self, x):
        d = torch.cdist(x, self.sym)
        a = torch.softmax(-d, -1)
        return x + (a @ self.sym - x)

class TurboEqualizationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, iters=3):
        super().__init__(); self.eq = nn.Linear(C, C); self.dec = nn.Linear(C, C); self.iters = iters
    def forward(self, x):
        h = self.eq(x)
        for _ in range(self.iters):
            h = h + self.dec(torch.tanh(h))
        return x + 0.1*h

class TrellisCodedModulationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.trans = nn.Linear(2*C, C)
    def forward(self, x):
        state = torch.zeros_like(x[:, :1]); outs = []
        for t in range(x.shape[1]):
            state = torch.tanh(self.trans(torch.cat([x[:,t:t+1], state], -1)))
            outs.append(state)
        return x + torch.cat(outs, 1)

class ExitChartMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.a = nn.Linear(C, C)
        self.b = nn.Linear(C, C)
    def forward(self, x):
        e1 = torch.sigmoid(self.a(x))
        e2 = torch.sigmoid(self.b(x))
        return x + 0.5*(e1-0.5) + 0.5*(e2-0.5)

class RateMatchedPuncturingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, p=0.4):
        super().__init__()
        self.p = p
        self.rec = nn.Linear(C, C)
    def forward(self, x):
        mask = (torch.rand_like(x[...,:1]) > self.p).float()
        punct = x * mask
        return x + self.rec(punct - x)

class ArithmeticSourceSeparationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.combine = nn.Linear(2*C, C)
    def forward(self, x):
        r = torch.rand_like(x)
        sep = torch.cat([x, r], -1)
        return x + self.combine(sep) - x

class SparseDictionaryMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=32):
        super().__init__()
        self.D = nn.Parameter(torch.randn(C, K))
    def forward(self, x):
        a = torch.relu(torch.einsum('btc,ck->btk', x, self.D))
        return x + (a @ self.D.T - x)

class MineMutualInfoMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.T = nn.Sequential(nn.Linear(2*C, C), nn.ReLU(), nn.Linear(C, 1))
    def forward(self, x):
        y = torch.roll(x, 1, dims=1)
        mi = self.T(torch.cat([x, y], -1))
        return x + 0.1*torch.tanh(mi)

class EntropicRegularizationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, beta=1.0):
        super().__init__()
        self.beta = beta
        self.proj = nn.Linear(C, C)
    def forward(self, x):
        w = torch.softmax(self.proj(x)/self.beta, -1)
        e = -(w*torch.log(w+1e-8)).sum(-1, keepdim=True)
        return x + e

class HankelMatrixMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, L=8):
        super().__init__(); self.L=L; self.fc=nn.Linear(C,C)
    def forward(self, x):
        h = x.unfold(1, self.L, 1).flatten(2)
        u,s,v = torch.svd(h.mean(0).to(x.dtype))
        rec = u[:,:,:h.size(2)].matmul((s[:,:h.size(2)].unsqueeze(0)*v.transpose(-1,-2)))
        return x + self.fc(rec.unflatten(2,(x.size(2),self.L)).mean(-1))

class PronyMethodMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, M=16):
        super().__init__(); self.M=M; self.fc=nn.Linear(C,C)
    def forward(self, x):
        B,T,C = x.shape
        idx = torch.linspace(0,1,T,device=x.device)
        bases = torch.exp(1j*idx[:,None]*torch.arange(self.M,device=x.device)*2*3.14159/T)
        coef = torch.linalg.lstsq(bases, x.mean(-1)).solution
        rec = (bases @ coef)
        return x + self.fc(rec.unsqueeze(-1).expand(B,T,C).real)

class CepstralMeanNormMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self, x):
        spec = torch.fft.rfft(x.float(), dim=1, n=2*x.size(1))
        cep = torch.fft.irfft(torch.log(spec.abs()+1e-6), dim=1, n=spec.size(1)*2)[:, :x.size(1)]
        cep = cep - cep.mean(1, keepdim=True)
        return x + self.fc(cep.to(x.dtype))

class GroupDelayMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.fc=nn.Linear(C,C)
    def forward(self, x):
        spec = torch.fft.rfft(x.float(), dim=1)
        ph = torch.angle(spec)
        gd = torch.gradient(ph, dim=1)[0]
        w = gd.abs().to(x.dtype)
        return x + self.fc((spec.real*w).to(x.dtype))

class ReassignmentSpectrumMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=32):
        super().__init__(); self.n=n; self.fc=nn.Linear(C,C)
    def forward(self, x):
        w = torch.hann_window(self.n, device=x.device)
        st = torch.stft(x.float(), self.n, hop_length=self.n//4, window=w, return_complex=True)
        mag = st.abs(); return x + self.fc(mag.mean(-1).to(x.dtype))

class TFReassignmentMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=32):
        super().__init__(); self.n=n; self.fc=nn.Linear(C,C)
    def forward(self, x):
        w = torch.hann_window(self.n, device=x.device)
        st = torch.stft(x.float(), self.n, hop_length=self.n//4, window=w, return_complex=True)
        c = (st * torch.arange(st.size(2),device=x.device)).abs().sum(-1)
        return x + self.fc(c.to(x.dtype))

class ConeKernelDistMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=32):
        super().__init__(); self.n=n; self.fc=nn.Linear(C,C)
    def forward(self, x):
        st = torch.stft(x.float(), self.n, hop_length=self.n//4, return_complex=True)
        prod = st.unsqueeze(2) * st.unsqueeze(1).conj()
        return x + self.fc(prod.diagonal(dim1=1,dim2=2).sum(-1).real.to(x.dtype))

class ZAMDistributionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=32):
        super().__init__(); self.n=n; self.fc=nn.Linear(C,C)
    def forward(self, x):
        st = torch.stft(x.float(), self.n, hop_length=self.n//4, return_complex=True)
        L = st.size(2)//2
        win = torch.triu(torch.ones(L,L,device=x.device))
        prod = st[...,:L].unsqueeze(2)*st[...,:L].unsqueeze(1).conj()
        return x + self.fc((prod*win).sum((-1,-2)).real.to(x.dtype))

class MultitaperSpectralMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, n=32, K=4):
        super().__init__(); self.n=n; self.K=K; self.fc=nn.Linear(C,C)
    def forward(self, x):
        taps = torch.signal.windows.dpss(self.n, 3, self.K, device=x.device)
        sp = torch.stack([torch.fft.rfft(x.float()*t, dim=1) for t in taps])
        return x + self.fc(sp.abs().mean(0).to(x.dtype))

class EmpiricalWaveletPacketMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, levels=3):
        super().__init__(); self.lv=levels; self.fc=nn.Linear(C,C)
    def forward(self, x):
        feats=[]
        for l in range(self.lv):
            f = torch.fft.rfft(x.float(), dim=1)
            feats.append(f.abs().to(x.dtype))
        return x + self.fc(torch.stack(feats).mean(0))

class ModifiedGroupDelayMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, alpha=0.5):
        super().__init__(); self.a=alpha; self.fc=nn.Linear(C,C)
    def forward(self, x):
        spec = torch.fft.rfft(x.float(), dim=1)
        gd = torch.gradient(torch.angle(spec), dim=1)[0]
        mod = gd.abs()/(spec.abs()**self.a + 1e-3)
        return x + self.fc(mod.to(x.dtype))

class LPCAllPoleMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, P=8):
        super().__init__(); self.P=P; self.c=nn.Parameter(torch.zeros(C,P)); self.fc=nn.Linear(C,C)
    def forward(self, x):
        past = x.unfold(1, self.P, 1)  # (B,T-P+1,C,P)
        pred = (past * self.c).sum(-1)
        res = x[:, self.P-1:] - pred
        return x + self.fc(res.to(x.dtype))

class MemristiveDynamicsMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)*0.1); self.a = nn.Parameter(torch.ones(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            g = torch.sigmoid(self.a * h.mean(-1, keepdim=True)).expand_as(h)
            h = (1-g)*h + g*(x[:,t] + torch.tanh(h @ self.W)); out.append(h)
        return torch.stack(out, 1)

class HamiltonianControlMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.J = nn.Parameter(torch.randn(C,C)*0.1); self.P = nn.Parameter(torch.randn(C,C)*0.1); self.K = nn.Parameter(torch.eye(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            J = self.J - self.J.t(); P = self.P.t()@self.P + 1e-3*torch.eye(C)
            flow = (J - P) @ (self.K @ h.t()).t(); h = h + 0.5*(x[:,t] - flow); out.append(h)
        return torch.stack(out, 1)

class FeedbackLinearizationMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.b = nn.Parameter(torch.zeros(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            nonlinear = torch.tanh(h @ self.W + self.b)
            v = x[:,t] - nonlinear; h = h + v @ self.W.t(); out.append(h)
        return torch.stack(out, 1)

class ConstrainedMPCCubicMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=4):
        super().__init__(); self.H = H; self.W = nn.Parameter(torch.randn(C,C)); self.ub = nn.Parameter(torch.tensor(3.0))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            for _ in range(self.H):
                h = torch.clamp(h + 0.3*(x[:,t]-h) @ self.W.t(), -self.ub, self.ub)
            out.append(h)
        return torch.stack(out, 1)

class SlidingModeObserverMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.lam = nn.Parameter(torch.ones(C)); self.k = nn.Parameter(torch.tensor(2.0))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            s = h - x[:,t]; h = h + (x[:,t]-h) @ self.W.t() - self.k*torch.tanh(s*self.lam)*self.lam; out.append(h)
        return torch.stack(out, 1)

class ExtendedKalmanMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.Q = nn.Parameter(torch.eye(C)); self.R = nn.Parameter(torch.eye(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); P = self.Q.expand(B,C,C).clone(); out = []
        for t in range(T):
            H = torch.tanh(h @ self.W); P = P + self.Q
            S = self.W.t()@P@self.W + self.R; K = P@self.W@torch.inverse(S)
            h = H + (K @ (x[:,t]-H).unsqueeze(-1)).squeeze(-1); P = (torch.eye(C)-K@self.W.t())@P; out.append(h)
        return torch.stack(out, 1)

class UnscentedKalmanMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.alpha = nn.Parameter(torch.tensor(1e-2))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            sp = torch.stack([h, h+self.alpha, h-self.alpha], 0); pred = torch.tanh(sp @ self.W).mean(0)
            cov = (pred-pred.mean(0)).pow(2).mean(0,keepdim=True).expand_as(h)
            h = pred + torch.sigmoid(cov)*(x[:,t]-pred); out.append(h)
        return torch.stack(out, 1)

class ParticleFilterMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, N=16):
        super().__init__(); self.N = N; self.W = nn.Parameter(torch.randn(C,C)*0.1); self.s = nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        B,T,C = x.shape; out = []
        for t in range(T):
            parts = torch.randn(B,self.N,C, device=x.device)*self.s
            w = -(parts @ self.W - x[:,t:t+1]).pow(2).mean(-1); w = torch.softmax(w,-1)
            h = (w.unsqueeze(-1)*parts).sum(1); out.append(h)
        return torch.stack(out, 1)

class BifurcationControlMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.mu = nn.Parameter(torch.zeros(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            r = torch.tanh(h @ self.W); h = (self.mu+1.0)*r + r.pow(3) - r.pow(5) + x[:,t]; out.append(h)
        return torch.stack(out, 1)

class ChaosSyncMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.k = nn.Parameter(torch.ones(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            drive = torch.tanh(x[:,t] @ self.W.t()); e = drive - torch.tanh(h @ self.W.t())
            h = h + 0.3*(x[:,t]-h) - self.k*e @ self.W; out.append(h)
        return torch.stack(out, 1)

class BasinShapingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.L = nn.Parameter(torch.eye(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            gradV = (h @ self.L) @ self.L.t(); h = h - 0.3*gradV + x[:,t]; out.append(h)
        return torch.stack(out, 1)

class PassivityControlMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.G = nn.Parameter(torch.eye(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            y = torch.tanh(h @ self.W.t()); u = -0.5*y - self.G@y + x[:,t]
            h = h + u @ self.W; out.append(h)
        return torch.stack(out, 1)

class OccupancyFieldMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=8):
        super().__init__()
        self.pos = nn.Parameter(torch.randn(1, H, C))
        self.W = nn.Parameter(torch.randn(C, C) * 0.1)
    def forward(self, x):
        occ = torch.sigmoid(x @ self.W)
        field = (occ.unsqueeze(1) * self.pos).sum(1)
        return x + 0.1 * field

class ConditionalNPMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.enc = nn.Linear(C, C, bias=False)
        self.dec = nn.Linear(C, C, bias=False)
    def forward(self, x):
        ctx = x.mean(1, keepdim=True)
        z = torch.tanh(self.enc(ctx))
        return x + 0.1 * self.dec(z).tanh()

class MAMLInnerLoopMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, steps=2, lr=0.1):
        super().__init__(); self.W = nn.Parameter(torch.randn(C, C) * 0.1); self.steps, self.lr = steps, lr
    def forward(self, x):
        W = self.W.clone()
        for _ in range(self.steps):
            g = (x.transpose(1,2) @ (x @ W) - x @ W).mean(0); W = W - self.lr * g
        return x + x @ W

class BOAcquisitionMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=8):
        super().__init__()
        self.mu = nn.Parameter(torch.randn(1, C))
        self.kappa = nn.Parameter(torch.tensor(1.0))
        self.att = nn.Linear(C, K, bias=False)
    def forward(self, x):
        ucb = self.mu + self.kappa * self.att(x).abs()
        w = torch.softmax(ucb, 1)
        return x + 0.1 * (w.unsqueeze(-1) * x.unsqueeze(2)).sum(2)

class ParticleFilterProposal(nn.Module):
    def __init__(self, C=128, T=128, dim=128, P=8):
        super().__init__()
        self.P = P
        self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        parts = x.unsqueeze(2).repeat(1,1,self.P,1)
        parts = parts + 0.1 * self.proj(parts)
        w = torch.softmax(parts.pow(2).mean(-1), -1)
        return (w.unsqueeze(-1) * parts).sum(2)

class RiemannianScoreMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, steps=2):
        super().__init__(); self.steps = steps; self.s = nn.Parameter(torch.randn(C)*0.1); self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        u = x / (x.norm(dim=-1, keepdim=True) + 1e-5)
        for _ in range(self.steps):
            u = u + 0.1 * (self.proj(u) - u @ self.s)
        return x + 0.1 * (u - x)

class RationalSplineFlow(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.w = nn.Parameter(torch.randn(C, C) * 0.1)
    def forward(self, x):
        y = x @ self.w
        y = y.tanh() + 0.1 * torch.sin(y)
        return x + 0.1 * y

class HierarchicalPriorVIMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, G=4):
        super().__init__(); self.G = G; self.mean = nn.Parameter(torch.zeros(G, C)); self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        g = x.view(x.size(0), self.G, -1, x.size(-1)).mean(2)
        z = torch.softmax(g @ self.mean.T, -1) @ self.mean
        z = z.repeat_interleave(x.size(1)//self.G, 1)
        return x + 0.1 * self.proj(z)

class IWAEMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=8):
        super().__init__()
        self.K = K
        self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        parts = x.unsqueeze(2).repeat(1,1,self.K,1)
        parts = parts + 0.1 * self.proj(parts)
        w = torch.softmax(parts.flatten(-2).pow(2).mean(-1), -1)
        return (w.unsqueeze(-1) * parts).sum(2)

class InfoMaxMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=8):
        super().__init__()
        self.proj = nn.Linear(C, K, bias=False)
        self.W = nn.Parameter(torch.randn(K, C) * 0.1)
    def forward(self, x):
        h = self.proj(x)
        score = h @ self.W
        return x + 0.1 * torch.tanh(score)

class OTControlMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.target = nn.Parameter(torch.randn(1, C))
        self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        w = torch.softmax(-((x - self.target).pow(2).sum(-1, keepdim=True)), 1)
        plan = (w * x).sum(1, keepdim=True)
        return x + 0.1 * self.proj(plan - x)

class TemperedPosteriorMix(nn.Module):
    def __init__(self, C=128, T=0.5, dim=128, P=8):
        super().__init__(); self.P = P; self.T = nn.Parameter(torch.tensor(T)); self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        parts = x.unsqueeze(2).repeat(1,1,self.P,1)
        e = -parts.pow(2).mean(-1) / self.T.clamp(0.1, 2.0)
        w = torch.softmax(e, -1)
        return (w.unsqueeze(-1) * (parts + 0.1*self.proj(parts))).sum(2)

class NTMControllerMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, mem=64, width=16):
        super().__init__(); self.M = nn.Parameter(torch.randn(mem, width))
        self.k = nn.Linear(C, width); self.beta = nn.Linear(C, 1)
    def forward(self, x):
        w = F.softmax(self.k(x) @ self.M.T, -1)
        return x + torch.sigmoid(self.beta(x)) * (w @ self.M).mean(-1, keepdim=True)

class DNCReaderMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, mem=64, width=16):
        super().__init__()
        self.M = nn.Parameter(torch.randn(mem, width))
        self.kread = nn.Linear(C, width)
    def forward(self, x):
        k = self.kread(x)
        w = F.softmax(k @ self.M.T, -1)
        r = (w @ self.M).mean(-1, keepdim=True)
        return x + torch.sigmoid(r)

class SparseCodingDictMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, K=32):
        super().__init__()
        self.D = nn.Parameter(torch.randn(K, C))
        self.iters = 3
    def forward(self, x):
        a = torch.relu(x @ self.D.T)
        for _ in range(self.iters):
            a = torch.relu(a + 0.2*(x @ self.D.T - a @ (self.D @ self.D.T)))
        return x + torch.tanh(a @ self.D)

class ActiveInferenceMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.prior = nn.Parameter(torch.zeros(C))
        self.W = nn.Linear(C, C)
    def forward(self, x):
        pred = self.W(x)
        err = x - pred
        surprise = torch.exp(-err.abs())
        return x + 0.1*(self.prior - x) * surprise

class SymbolGroundingMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, S=16):
        super().__init__()
        self.emb = nn.Parameter(torch.randn(S, C))
        self.attn = nn.Linear(C, S)
    def forward(self, x):
        w = F.softmax(self.attn(x), -1)
        grounded = w @ self.emb
        return x + 0.1*grounded

class CompositionalGenMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.role = nn.Linear(C, C)
        self.fill = nn.Linear(C, C)
    def forward(self, x):
        r = self.role(x)
        f = self.fill(x)
        return x + 0.1*torch.tanh(r + f)

class MentalRolloutMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=3):
        super().__init__()
        self.trans = nn.Linear(C, C)
        self.H = H
    def forward(self, x):
        sim = x
        for _ in range(self.H):
            sim = self.trans(sim)
        return x + 0.1*torch.tanh(sim - x)

class BayesianSurpriseMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.mu = nn.Parameter(torch.zeros(C))
        self.sig = nn.Parameter(torch.ones(C))
    def forward(self, x):
        surprise = 0.5*((x - self.mu)**2/self.sig**2 + torch.log(self.sig**2))
        g = torch.sigmoid(surprise.mean(-1, keepdim=True))
        self.mu.data += 0.05*(x - self.mu).mean(0)
        return x + 0.05*g*(x - self.mu)

class ConflictMonitorMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.g = nn.Linear(C, C)
        self.h = nn.Linear(C, C)
    def forward(self, x):
        conflict = (self.g(x) - self.h(x)).abs().mean(-1, keepdim=True)
        ctrl = torch.sigmoid(conflict)
        return x + ctrl * (self.g(x) - x)

class Retinotopic2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.k = nn.Parameter(torch.ones(1))
    def forward(self, x):
        b,c,h,w = x.shape
        yy,xx = torch.meshgrid(torch.arange(h,device=x.device).float()/h-0.5, torch.arange(w,device=x.device).float()/w-0.5)
        r = (yy**2+xx**2).sqrt().view(1,1,h,w)
        return x * torch.sigmoid(self.k*(1.0-r))

class LateralInhib2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.k = nn.Parameter(torch.tensor(0.3))
    def forward(self, x):
        avg = torch.nn.functional.avg_pool2d(x, 3, 1, 1)
        return x + torch.sigmoid(self.k)*(x - avg)

class WavePropag2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.a = nn.Parameter(torch.tensor(1.0))
    def forward(self, x):
        lap = x[:,:,2:,1:-1]+x[:,:,1:-1,2:]+x[:,:,:-2,1:-1]+x[:,:,1:-1,:-2]-4*x[:,:,1:-1,1:-1]
        y = x.clone(); y[:,:,1:-1,1:-1] = x[:,:,1:-1,1:-1] + self.a*lap
        return y

class NavierStokes2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.v = nn.Parameter(torch.zeros(2))
    def forward(self, x):
        b,c,h,w = x.shape
        g = torch.stack(torch.meshgrid(torch.linspace(-1,1,h,device=x.device), torch.linspace(-1,1,w,device=x.device)),-1)
        g = g.unsqueeze(0).expand(b,h,w,2) + 0.1*torch.tanh(self.v).view(1,1,1,2)
        return torch.nn.functional.grid_sample(x, g, align_corners=False)

class Poisson2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.iters = 3
    def forward(self, x):
        for _ in range(self.iters):
            x = x + 0.25*(torch.nn.functional.avg_pool2d(x,3,1,1)-x)
        return x

class Maxwell2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.w = nn.Parameter(torch.ones(1))
    def forward(self, x):
        gx = x[:,:,1:-1,2:]-x[:,:,1:-1,:-2]
        gy = x[:,:,2:,1:-1]-x[:,:,:-2,1:-1]
        y = x.clone(); y[:,:,1:-1,1:-1] = torch.tanh(self.w*(gx-gy))
        return y

class Mobius2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.k = nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        b,c,h,w = x.shape
        r = torch.stack(torch.meshgrid(torch.arange(h,device=x.device).float()/h-0.5, torch.arange(w,device=x.device).float()/w-0.5),-1).pow(2).sum(-1).sqrt().view(1,1,h,w)
        return x * (1.0 + self.k*r)/(1.0 + r)

class LieRot2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.theta = nn.Parameter(torch.zeros(1))
    def forward(self, x):
        b,c,h,w = x.shape
        ct,st = torch.cos(self.theta), torch.sin(self.theta)
        yy,xx = torch.meshgrid(torch.linspace(-1,1,h,device=x.device), torch.linspace(-1,1,w,device=x.device))
        g = torch.stack([xx*ct-yy*st, xx*st+yy*ct],-1).unsqueeze(0).expand(b,h,w,2)
        return torch.nn.functional.grid_sample(x, g, align_corners=False)

class Fract2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.s = nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        sf = float(self.s.clamp(0.3,0.7))
        x = torch.nn.functional.interpolate(x, scale_factor=sf, mode='bilinear', align_corners=False)
        return torch.nn.functional.interpolate(x, (x.shape[2], x.shape[3]), mode='bilinear', align_corners=False)

class WaveletPacket2d(nn.Module):
    def __init__(self, C=128, T=128, dim=16):
        super().__init__(); self.g = nn.Parameter(torch.ones(1))
    def forward(self, x):  # (B, C, H, W)
        lo = torch.nn.functional.avg_pool2d(x, 2, 2)
        lo_up = torch.nn.functional.interpolate(lo, (x.shape[2], x.shape[3]), mode='nearest')
        hi = x - lo_up
        g = torch.tanh(self.g)
        return g * lo_up + (1 - g) * hi

class LdpcBp2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.w = nn.Parameter(torch.ones(1))
    def forward(self, x):
        msg = torch.nn.functional.avg_pool2d(x,3,1,1)
        return x + torch.sigmoid(self.w)*(msg - x)

class Huffman2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.g = nn.Parameter(torch.ones(1))
    def forward(self, x):
        var = x.var(dim=(2,3), keepdim=True)
        w = torch.sigmoid(self.g*var)
        return x * w

class Gabor2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.theta = nn.Parameter(torch.zeros(1))
    def forward(self, x):
        b,c,h,w = x.shape
        ct,st = torch.cos(self.theta), torch.sin(self.theta)
        yy,xx = torch.meshgrid(torch.linspace(-1,1,h,device=x.device), torch.linspace(-1,1,w,device=x.device))
        g = torch.exp(-(xx*ct-yy*st)**2-0.5*(xx*st+yy*ct)**2)
        return x * g.view(1,1,h,w)

class Shearlet2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.a = nn.Parameter(torch.tensor(0.5))
    def forward(self, x):
        gx = x[:,:,1:-1,2:]-x[:,:,1:-1,:-2]
        gy = x[:,:,2:,1:-1]-x[:,:,:-2,1:-1]
        y = x.clone(); y[:,:,1:-1,1:-1] = torch.tanh(self.a*gx + (1-self.a)*gy)
        return y

class Curvelet2d(nn.Module):
    def __init__(self, dim=16):
        super().__init__(); self.k = nn.Parameter(torch.tensor(2.0))
    def forward(self, x):
        lap = x[:,:,2:,1:-1]+x[:,:,1:-1,2:]+x[:,:,:-2,1:-1]+x[:,:,1:-1,:-2]-4*x[:,:,1:-1,1:-1]
        y = x.clone(); y[:,:,1:-1,1:-1] = torch.sigmoid(self.k*lap)
        return y

