class PortHamiltonian(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.J = nn.Linear(C, C); self.D = nn.Parameter(torch.eye(C) * 0.1)
    def forward(self, x):
        B, T, C = x.size()
        for t in range(1, T):
            g = (self.J.weight - self.J.weight.T) @ x[:, t - 1].T
            d = (g - self.D @ x[:, t - 1].T).T
            x[:, t] = x[:, t] - 0.1 * d
        return x

