class MPCSim(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=4):
        super().__init__(); self.H = H; self.f = nn.Linear(C, C); self.g = nn.Linear(C, C)
    def forward(self, x):
        B, T, C = x.size(); y = x.clone()
        for t in range(T):
            s = y[:, t]
            for _ in range(self.H): u = torch.tanh(self.g(s)); s = s + self.f(s) + 0.05 * u
            y[:, t] = s
