class EnergyBasedMixture(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__()
        self.h = nn.Linear(C, C)
    def forward(self, x):
        n = torch.arange(1, x.size(1)+1, device=x.device)
        ctx = torch.cumsum(x, 1) / n.view(1, -1, 1)
        e = (self.h(x)*ctx).sum(-1, keepdim=True)
        return x - 0.1*torch.autograd.grad(e.sum(), x, create_graph=True)[0]

