class RetinotopicMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, k=3):
        super().__init__(); self.k=k
        self.w=nn.Parameter(torch.ones(k,k)/k**2)
    def forward(self,x):
        B,T,C=x.shape; s=int(math.ceil(T**0.5))
        g=torch.zeros(B,s*s,C,device=x.device); g[:, :T]=x
        g=g.view(B,s,s,C).permute(0,3,1,2)
        out=F.conv2d(g,self.w.expand(C,1,self.k,self.k).clone().unsqueeze(1),groups=C,padding=self.k//2)
        return out.permute(0,2,3,1).reshape(B,s*s,C)[:,:T]

