class LPCAllPoleMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, P=8):
        super().__init__(); self.P=P; self.c=nn.Parameter(torch.zeros(C,P)); self.fc=nn.Linear(C,C)
    def forward(self, x):
        past = x.unfold(1, self.P, 1)  # (B,T-P+1,C,P)
        pred = (past * self.c).sum(-1)
        res = x[:, self.P-1:] - pred
        return x + self.fc(res.to(x.dtype))

