class PassivityControlMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128):
        super().__init__(); self.W = nn.Parameter(torch.randn(C,C)); self.G = nn.Parameter(torch.eye(C))
    def forward(self, x):
        B,T,C = x.shape; h = x.new_zeros(B,C); out = []
        for t in range(T):
            y = torch.tanh(h @ self.W.t()); u = -0.5*y - self.G@y + x[:,t]
            h = h + u @ self.W; out.append(h)
        return torch.stack(out, 1)

class OccupancyFieldMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, H=8):
        super().__init__()
        self.pos = nn.Parameter(torch.randn(1, H, C))
        self.W = nn.Parameter(torch.randn(C, C) * 0.1)
    def forward(self, x):
        occ = torch.sigmoid(x @ self.W)
        field = (occ.unsqueeze(1) * self.pos).sum(1)
        return x + 0.1 * field

