class RicciFlowMix(nn.Module):
    def __init__(self, C=128, T=128, dim=128, steps=2):
        super().__init__()
        self.steps = steps
        self.w = nn.Parameter(torch.randn(C, 1))
    def forward(self, x):  # (B, C, T)
        g = self.w.view(1, C, 1)
        for _ in range(self.steps):
