        super().__init__()
        self.K = K
        self.proj = nn.Linear(C, C, bias=False)
    def forward(self, x):
        parts = x.unsqueeze(2).repeat(1,1,self.K,1)
        parts = parts + 0.1 * self.proj(parts)
